def tokenize(sql):
    toks = []
    i, n = 0, len(sql)
    while i < n:
        c = sql[i]
        if c.isspace():
            i += 1
        elif c == "'":
            j = i + 1
            buf = []
            while True:
                if j >= n:
                    raise SQLError("unterminated string")
                if sql[j] == "'":
                    if j + 1 < n and sql[j + 1] == "'":
                        buf.append("'")
                        j += 2
                        continue
                    break
                buf.append(sql[j])
                j += 1
            toks.append(("str", "".join(buf)))
            i = j + 1
        elif c.isdigit():
            j = i
            while j < n and sql[j].isdigit():
                j += 1
            toks.append(("num", int(sql[i:j])))
            i = j
        elif c.isalpha() or c == "_":
            j = i
            while j < n and (sql[j].isalnum() or sql[j] == "_"):
                j += 1
            w = sql[i:j]
            if w.upper() in KEYWORDS:
                toks.append(("kw", w.upper()))
            else:
                toks.append(("id", w))
            i = j
        elif sql[i:i + 2] in ("||", "!=", "<>", "<=", ">=", "=="):
            toks.append(("op", sql[i:i + 2]))
            i += 2
        elif c in "+-*/%=<>(),;.":
            toks.append(("op", c))
            i += 1
        else:
            raise SQLError("bad character %r" % c)
    toks.append(("eof", None))
    return toks


