_NUM = re.compile(r"\s*[+-]?\d+(\.\d*)?")


def to_num(v):
    if isinstance(v, str):
        m = _NUM.match(v)
        if not m:
            return 0
        s = m.group(0)
        return int(float(s)) if "." in s else int(s)
    return v


def to_text(v):
    return v if isinstance(v, str) else str(v)


def truth(v):
    if v is None:
        return None
    if isinstance(v, str):
        v = to_num(v)
    return 1 if v != 0 else 0


def compare(a, b):
    ta = 1 if isinstance(a, str) else 0
    tb = 1 if isinstance(b, str) else 0
    if ta != tb:
        return -1 if ta < tb else 1
    return (a > b) - (a < b)


def like(s, pat):
    rx = "".join(".*" if c == "%" else "." if c == "_" else re.escape(c) for c in pat)
    return re.fullmatch(rx, s, re.S | re.I) is not None


def evaluate(e, row=None):
    op = e[0]
    if op == "lit":
        return e[1]
    if op == "col":
        if row is None or e[1] not in row:
            raise SQLError("no such column: " + e[1])
        return row[e[1]]
    if op == "neg":
        v = evaluate(e[1], row)
        return None if v is None else -to_num(v)
    if op == "arith":
        a, b = evaluate(e[2], row), evaluate(e[3], row)
        if a is None or b is None:
            return None
        a, b = to_num(a), to_num(b)
        o = e[1]
        if o == "+":
            return a + b
        if o == "-":
            return a - b
        if o == "*":
            return a * b
        if b == 0:
            return None
        q = abs(a) // abs(b)
        if o == "/":
            return q if (a >= 0) == (b >= 0) else -q
        return a - b * (q if (a >= 0) == (b >= 0) else -q)
    if op == "concat":
        a, b = evaluate(e[1], row), evaluate(e[2], row)
        if a is None or b is None:
            return None
        return to_text(a) + to_text(b)
    if op == "cmp":
        a, b = evaluate(e[2], row), evaluate(e[3], row)
        if a is None or b is None:
            return None
        c = compare(a, b)
        return int({"=": c == 0, "!=": c != 0, "<": c < 0, "<=": c <= 0,
                    ">": c > 0, ">=": c >= 0}[e[1]])
    if op == "and":
        a = truth(evaluate(e[1], row))
        if a == 0:
            return 0
        b = truth(evaluate(e[2], row))
        if b == 0:
            return 0
        return None if a is None or b is None else 1
    if op == "or":
        a = truth(evaluate(e[1], row))
        if a == 1:
            return 1
        b = truth(evaluate(e[2], row))
        if b == 1:
            return 1
        return None if a is None or b is None else 0
    if op == "not":
        a = truth(evaluate(e[1], row))
        return None if a is None else 1 - a
    if op == "isnull":
        r = evaluate(e[1], row) is None
        return int(r != e[2])
    if op == "in":
        x = evaluate(e[1], row)
        res = 0
        if x is None:
            res = None if e[2] else 0
        else:
            for it in e[2]:
                v = evaluate(it, row)
                if v is None:
                    res = None
                elif compare(x, v) == 0:
                    res = 1
                    break
        if res is None:
            return None
        return 1 - res if e[3] else res
    if op == "like":
        a, p = evaluate(e[1], row), evaluate(e[2], row)
        if a is None or p is None:
            return None
        r = int(like(to_text(a), to_text(p)))
        return 1 - r if e[3] else r
    if op == "between":
        x, lo, hi = (evaluate(e[i], row) for i in (1, 2, 3))
        if x is None:
            r = None
            if lo is not None and hi is not None:
                r = None
        else:
            c1 = None if lo is None else int(compare(x, lo) >= 0)
            c2 = None if hi is None else int(compare(x, hi) <= 0)
            if c1 == 0 or c2 == 0:
                r = 0
            elif c1 is None or c2 is None:
                r = None
            else:
                r = 1
        if r is None:
            return None
        return 1 - r if e[4] else r
    if op == "case":
        if e[1] is None:
            for c, v in e[2]:
                if truth(evaluate(c, row)) == 1:
                    return evaluate(v, row)
        else:
            x = evaluate(e[1], row)
            if x is not None:
                for c, v in e[2]:
                    w = evaluate(c, row)
                    if w is not None and compare(x, w) == 0:
                        return evaluate(v, row)
        return None if e[3] is None else evaluate(e[3], row)
    if op == "func":
        return call(e[1], e[2], row)
    raise SQLError("bad expression")


def call(name, argexprs, row):
    if name == "COALESCE":
        for a in argexprs:
            v = evaluate(a, row)
            if v is not None:
                return v
        return None
    args = [evaluate(a, row) for a in argexprs]
    if name == "NULLIF":
        if len(args) != 2:
            raise SQLError("NULLIF takes 2 arguments")
        a, b = args
        return None if a is not None and b is not None and compare(a, b) == 0 else a
    if name in ("UPPER", "LOWER", "LENGTH", "ABS"):
        if len(args) != 1:
            raise SQLError(name + " takes 1 argument")
    elif name == "SUBSTR":
        if len(args) not in (2, 3):
            raise SQLError("SUBSTR takes 2 or 3 arguments")
    else:
        raise SQLError("no such function: " + name)
    if args[0] is None:
        return None
    a = args[0]
    if name == "UPPER":
        return to_text(a).upper()
    if name == "LOWER":
        return to_text(a).lower()
    if name == "LENGTH":
        return len(to_text(a))
    if name == "ABS":
        return abs(to_num(a))
    s = to_text(a)
    if args[1] is None or (len(args) == 3 and args[2] is None):
        return None
    start = to_num(args[1])
    if len(args) == 3:
        ln = to_num(args[2])
    else:
        ln = len(s) + 1 - start if start > 0 else len(s) + abs(start) + 1
    if start > 0:
        b = start - 1
    elif start < 0:
        b = len(s) + start
    else:
        b = -1
    if ln < 0:
        b, ln = b + ln, -ln
    e = b + ln
    b = max(b, 0)
    e = max(min(e, len(s)), b)
    return s[b:e]


class Database:
    def __init__(self, tables):
        self.tables = tables

    def query(self, sql):
        items = Parser(sql).parse_select()
        return [tuple(evaluate(e) for e, _ in items)]
