from functools import cmp_to_key


def sort_cmp(a, b):
    if a is None or b is None:
        return (a is not None) - (b is not None)
    return compare(a, b)


class Database:
    def __init__(self, tables):
        self.tables = {k.lower(): v for k, v in tables.items()}

    def query(self, sql):
        q = Parser(sql).parse_select()
        if q["table"] is None:
            envs = [{}]
            cols = []
        else:
            t = self.tables.get(q["table"].lower())
            if t is None:
                raise SQLError("no such table: " + q["table"])
            cols = [c.lower() for c in t[0]]
            qual = (q["alias"] or q["table"]).lower()
            envs = []
            for r in t[1]:
                env = {}
                for c, v in zip(cols, r):
                    env[c] = v
                    env[qual + "." + c] = v
                envs.append(env)
        if q["where"] is not None:
            envs = [e for e in envs if truth(evaluate(q["where"], e)) == 1]
        # expand select items
        items = []
        for e, name in q["items"]:
            if e[0] == "star":
                if e[1] is not None and e[1].lower() != qual:
                    raise SQLError("no such table: " + e[1])
                items += [(("col", c), c) for c in cols]
            else:
                items.append((e, name))
        rows = []
        for env in envs:
            out = tuple(evaluate(e, env) for e, _ in items)
            keys = []
            for te, desc in q["order"]:
                keys.append(self.order_value(te, items, out, env))
            rows.append((out, keys))
        if q["distinct"]:
            seen, uniq = set(), []
            for r in rows:
                if r[0] not in seen:
                    seen.add(r[0])
                    uniq.append(r)
            rows = uniq
        for i in reversed(range(len(q["order"]))):
            rows.sort(key=cmp_to_key(lambda a, b, i=i: sort_cmp(a[1][i], b[1][i])),
                      reverse=q["order"][i][1])
        res = [r[0] for r in rows]
        off = evaluate(q["offset"]) if q["offset"] is not None else 0
        if q["limit"] is not None:
            lim = evaluate(q["limit"])
            res = res[off:] if lim < 0 else res[off:off + lim]
        elif off:
            res = res[off:]
        return res

    @staticmethod
    def order_value(te, items, out, env):
        if te[0] == "lit" and isinstance(te[1], int):
            if not 1 <= te[1] <= len(items):
                raise SQLError("ORDER BY position out of range")
            return out[te[1] - 1]
        if te[0] == "col" and "." not in te[1]:
            for i, (_, name) in enumerate(items):
                if name is not None and name.lower() == te[1].lower():
                    return out[i]
        return evaluate(te, env)
