import re

_NUM = re.compile(r"\s*[+-]?\d+(\.\d*)?")


def to_num(v):
    if isinstance(v, str):
        m = _NUM.match(v)
        if not m:
            return 0
        s = m.group(0)
        return int(float(s)) if "." in s else int(s)
    return v


def to_text(v):
    return v if isinstance(v, str) else str(v)


def truth(v):
    if v is None:
        return None
    return 1 if to_num(v) != 0 else 0


def compare(a, b):
    ta = 1 if isinstance(a, str) else 0
    tb = 1 if isinstance(b, str) else 0
    if ta != tb:
        return -1 if ta < tb else 1
    return (a > b) - (a < b)


def like(s, pat):
    rx = "".join(".*" if c == "%" else "." if c == "_" else re.escape(c) for c in pat)
    return re.fullmatch(rx, s, re.S | re.I) is not None


def arith(o, a, b):
    if a is None or b is None:
        return None
    a, b = to_num(a), to_num(b)
    if o == "+":
        return a + b
    if o == "-":
        return a - b
    if o == "*":
        return a * b
    if b == 0:
        return None
    q = abs(a) // abs(b)
    if (a >= 0) != (b >= 0):
        q = -q
    return q if o == "/" else a - b * q


def substr(s, start, ln=None):
    if ln is None:
        ln = len(s) + 1 - start if start > 0 else len(s) + abs(start) + 1
    if start > 0:
        b = start - 1
    elif start < 0:
        b = len(s) + start
    else:
        b = -1
    if ln < 0:
        b, ln = b + ln, -ln
    e = b + ln
    b = max(b, 0)
    e = max(min(e, len(s)), b)
    return s[b:e]
