from .lexer import SQLError
from .parser import Parser
from .values import to_num, to_text, truth, compare, like, arith, substr


def evaluate(e, row=None):
    op = e[0]
    ev = lambda x: evaluate(x, row)
    if op == "lit":
        return e[1]
    if op == "col":
        if row is None or e[1] not in row:
            raise SQLError("no such column: " + e[1])
        return row[e[1]]
    if op == "neg":
        v = ev(e[1])
        return None if v is None else -to_num(v)
    if op == "arith":
        return arith(e[1], ev(e[2]), ev(e[3]))
    if op == "concat":
        a, b = ev(e[1]), ev(e[2])
        return None if a is None or b is None else to_text(a) + to_text(b)
    if op == "cmp":
        a, b = ev(e[2]), ev(e[3])
        if a is None or b is None:
            return None
        c = compare(a, b)
        return int({"=": c == 0, "!=": c != 0, "<": c < 0, "<=": c <= 0,
                    ">": c > 0, ">=": c >= 0}[e[1]])
    if op in ("and", "or"):
        dom = 0 if op == "and" else 1
        a = truth(ev(e[1]))
        if a == dom:
            return dom
        b = truth(ev(e[2]))
        if b == dom:
            return dom
        return None if a is None or b is None else 1 - dom
    if op == "not":
        a = truth(ev(e[1]))
        return None if a is None else 1 - a
    if op == "isnull":
        return int((ev(e[1]) is None) != e[2])
    if op == "in":
        return in_expr(e, ev)
    if op == "like":
        a, p = ev(e[1]), ev(e[2])
        if a is None or p is None:
            return None
        r = int(like(to_text(a), to_text(p)))
        return 1 - r if e[3] else r
    if op == "between":
        x, lo, hi = ev(e[1]), ev(e[2]), ev(e[3])
        c1 = None if x is None or lo is None else int(compare(x, lo) >= 0)
        c2 = None if x is None or hi is None else int(compare(x, hi) <= 0)
        if c1 == 0 or c2 == 0:
            r = 0
        elif c1 is None or c2 is None:
            return None
        else:
            r = 1
        return 1 - r if e[4] else r
    if op == "case":
        return case_expr(e, ev)
    if op == "func":
        return call(e[1], e[2], ev)
    raise SQLError("bad expression")


def in_expr(e, ev):
    x = ev(e[1])
    if x is None:
        return None if e[2] else (1 if e[3] else 0)
    res = 0
    for it in e[2]:
        v = ev(it)
        if v is None:
            res = None
        elif compare(x, v) == 0:
            res = 1
            break
    if res is None:
        return None
    return 1 - res if e[3] else res


def case_expr(e, ev):
    if e[1] is None:
        for c, v in e[2]:
            if truth(ev(c)) == 1:
                return ev(v)
    else:
        x = ev(e[1])
        if x is not None:
            for c, v in e[2]:
                w = ev(c)
                if w is not None and compare(x, w) == 0:
                    return ev(v)
    return None if e[3] is None else ev(e[3])


def call(name, argexprs, ev):
    if name == "COALESCE":
        for a in argexprs:
            v = ev(a)
            if v is not None:
                return v
        return None
    args = [ev(a) for a in argexprs]
    n = len(args)
    if name == "NULLIF" and n == 2:
        a, b = args
        return None if a is not None and b is not None and compare(a, b) == 0 else a
    if name in ("UPPER", "LOWER", "LENGTH", "ABS") and n == 1:
        a = args[0]
        if a is None:
            return None
        return {"UPPER": lambda: to_text(a).upper(), "LOWER": lambda: to_text(a).lower(),
                "LENGTH": lambda: len(to_text(a)), "ABS": lambda: abs(to_num(a))}[name]()
    if name == "SUBSTR" and n in (2, 3):
        if any(a is None for a in args):
            return None
        return substr(to_text(args[0]), to_num(args[1]),
                      to_num(args[2]) if n == 3 else None)
    raise SQLError("no such function or bad arguments: " + name)


class Database:
    def __init__(self, tables):
        self.tables = tables

    def query(self, sql):
        items = Parser(sql).parse_select()
        return [tuple(evaluate(e) for e, _ in items)]
