class SQLError(Exception):
    pass


TOKEN_RE = re.compile(r"""\s*(?:
    (?P<num>\d+)
  | (?P<str>'(?:[^']|'')*')
  | (?P<id>[A-Za-z_][A-Za-z_0-9]*)
  | (?P<op><>|!=|<=|>=|\|\||[-+*/%(),;<>=.])
