    def or_(self):
        l = self.and_()
        while self.kw("OR"):
            self.i += 1
            l = ("or", l, self.and_())
        return l

    def and_(self):
        l = self.not_()
        while self.kw("AND"):
            self.i += 1
            l = ("and", l, self.not_())
        return l

    def not_(self):
        if self.kw("NOT"):
            self.i += 1
            return ("not", self.not_())
        return self.cmp()
