        if self.op("+"):
            self.i += 1
            return self.unary()
        return self.primary()

    def primary(self):
        k, v = self.next()
        if k in ("num", "str"):
            return ("lit", v)
        if k == "op" and v == "(":
            e = self.expr()
            self.expect_op(")")
            return e
        if k == "id":
            u = v.upper()
            if u == "NULL":
                return ("lit", None)
            if u == "CASE":
                return self.case()
            if self.op("("):
                self.i += 1
                args = self.exprlist()
                self.expect_op(")")
                return ("func", u, args)
            return ("col", v)
        raise SQLError("unexpected token %r" % ((k, v),))

    def case(self):
        base = None
        if not self.kw("WHEN"):
            base = self.expr()
        whens = []
        while self.kw("WHEN"):
            self.i += 1
            c = self.expr()
            self.expect_kw("THEN")
            whens.append((c, self.expr()))
        els = None
        if self.kw("ELSE"):
            self.i += 1
            els = self.expr()
        self.expect_kw("END")
        return ("case", base, whens, els)
