import re
from .parser import SQLError


def to_num(v):
    if isinstance(v, str):
        m = re.match(r"\s*[-+]?\d+", v)
        return int(m.group()) if m else 0
    return v


def truth(v):
    return None if v is None else (1 if to_num(v) != 0 else 0)


def sortkey(v):
    return (1, v) if isinstance(v, str) else (0, v)


def compare(op, a, b):
    if a is None or b is None:
        return None
    a, b = sortkey(a), sortkey(b)
    return int({"=": a == b, "!=": a != b, "<": a < b, "<=": a <= b,
                ">": a > b, ">=": a >= b}[op])


def text(v):
    return v if isinstance(v, str) else str(v)


def like(s, p):
    rx = "".join(".*" if c == "%" else "." if c == "_" else re.escape(c) for c in p)
    return re.fullmatch(rx, s, re.S | re.I) is not None


def substr(s, start, length=None):
    n = len(s)
    if start < 0:
        start = n + start + 1
    if length is None:
        end = n + 1
    else:
        end = start + length
        if length < 0:
            start, end = end, start
    start = max(start, 1)
    end = min(end, n + 1)
    return s[start - 1:end - 1] if end > start else ""


def arith(o, a, b):
    if a is None or b is None:
        return None
    a, b = to_num(a), to_num(b)
    if o == "+":
        return a + b
    if o == "-":
        return a - b
    if o == "*":
        return a * b
    if b == 0:
        return None
    if o == "/":
        q = abs(a) // abs(b)
        return q if (a < 0) == (b < 0) else -q
    r = abs(a) % abs(b)
    return -r if a < 0 else r


def and3(a, b):
    if a == 0 or b == 0:
        return 0
    return None if a is None or b is None else 1
