from .parser import SQLError
from .values import compare, text, to_num, substr


def func(name, args):
    n = len(args)
    if name == "COALESCE":
        for a in args:
            if a is not None:
                return a
        return None
    if name == "NULLIF":
        if n != 2:
            raise SQLError("NULLIF takes 2 arguments")
        return None if compare("=", args[0], args[1]) == 1 else args[0]
    want = {"UPPER": (1,), "LOWER": (1,), "LENGTH": (1,), "ABS": (1,), "SUBSTR": (2, 3)}
    if name not in want:
        raise SQLError("no such function: %s" % name)
    if n not in want[name]:
        raise SQLError("wrong number of arguments to %s" % name)
    if any(x is None for x in args):
        return None
    a = args[0]
    if name == "UPPER":
        return text(a).upper()
    if name == "LOWER":
        return text(a).lower()
    if name == "LENGTH":
        return len(text(a))
    if name == "ABS":
        return abs(to_num(a))
    return substr(text(a), to_num(args[1]), to_num(args[2]) if n == 3 else None)
