from .parser import Parser, tokenize, SQLError
from .values import (to_num, truth, compare, text, like, arith, and3)
from .funcs import func


def ev(e, row=None):
    k = e[0]
    if k == "lit":
        return e[1]
    if k == "neg":
        v = ev(e[1], row)
        return None if v is None else -to_num(v)
    if k == "arith":
        return arith(e[1], ev(e[2], row), ev(e[3], row))
    if k == "concat":
        a, b = ev(e[1], row), ev(e[2], row)
        return None if a is None or b is None else text(a) + text(b)
    if k == "cmp":
        return compare(e[1], ev(e[2], row), ev(e[3], row))
    if k == "and":
        a = truth(ev(e[1], row))
        return 0 if a == 0 else and3(a, truth(ev(e[2], row)))
    if k == "or":
        a = truth(ev(e[1], row))
        if a == 1:
            return 1
        b = truth(ev(e[2], row))
        if b == 1:
            return 1
        return None if a is None or b is None else 0
    if k == "not":
        a = truth(ev(e[1], row))
        return None if a is None else 1 - a
    if k == "isnull":
        return int((ev(e[1], row) is None) != e[2])
    if k == "between":
        v, lo, hi = ev(e[1], row), ev(e[2], row), ev(e[3], row)
        r = and3(compare(">=", v, lo), compare("<=", v, hi))
        return r if r is None or not e[4] else 1 - r
    if k == "in":
        v = ev(e[1], row)
        if v is None:
            return None
        res = 0
        for it in e[2]:
            c = compare("=", v, ev(it, row))
            if c == 1:
                res = 1
                break
            if c is None:
                res = None
        return res if res is None or not e[3] else 1 - res
    if k == "like":
        v, p = ev(e[1], row), ev(e[2], row)
        if v is None or p is None:
            return None
        r = int(like(text(v), text(p)))
        return 1 - r if e[3] else r
    if k == "case":
        _, base, whens, els = e
        bv = ev(base, row) if base is not None else None
        for c, r in whens:
            if base is None:
                if truth(ev(c, row)) == 1:
                    return ev(r, row)
            elif compare("=", bv, ev(c, row)) == 1:
                return ev(r, row)
        return ev(els, row) if els is not None else None
    if k == "func":
        return func(e[1], [ev(a, row) for a in e[2]])
    raise SQLError("cannot evaluate %r" % (k,))


class Database:
    def __init__(self, tables):
        self.tables = tables

    def query(self, sql):
        items = Parser(tokenize(sql)).parse_select()
        return [tuple(ev(e) for e, _ in items)]
