from .parser import SQLError


class Scope:
    """One row of a FROM clause: columns are (table alias, column name)."""

    def __init__(self, cols, values):
        self.cols, self.values = cols, values

    def lookup(self, name, table):
        name = name.lower()
        table = table.lower() if table else None
        found = [i for i, (t, c) in enumerate(self.cols)
                 if c.lower() == name and (table is None or t.lower() == table)]
        if not found:
            raise SQLError("no such column: %s" % (table + "." + name if table else name))
        if len(found) > 1:
            raise SQLError("ambiguous column name: %s" % name)
        return self.values[found[0]]


def okey(v):
    return (0, 0) if v is None else (2, v) if isinstance(v, str) else (1, v)
