import re


class SQLError(Exception):
    pass


TOKEN_RE = re.compile(r"""\s*(?:
    (?P<num>\d+)
  | (?P<str>'(?:[^']|'')*')
  | (?P<id>[A-Za-z_][A-Za-z_0-9]*)
  | (?P<op><>|!=|<=|>=|\|\||[-+*/%(),;<>=.])
)""", re.X)


def tokenize(sql):
    pos, out = 0, []
    sql = sql.rstrip()
    while pos < len(sql):
        m = TOKEN_RE.match(sql, pos)
        if not m:
            raise SQLError("bad token at %r" % sql[pos:pos + 10])
        pos = m.end()
        if m.group("num"):
            out.append(("num", int(m.group("num"))))
        elif m.group("str") is not None:
            out.append(("str", m.group("str")[1:-1].replace("''", "'")))
        elif m.group("id"):
            out.append(("id", m.group("id")))
        else:
            out.append(("op", m.group("op")))
    out.append(("end", None))
    return out


CMP = {"=", "!=", "<>", "<", "<=", ">", ">="}


class Parser:
    def __init__(self, toks):
        self.t = toks
        self.i = 0

    def peek(self):
        return self.t[self.i]

    def kw(self, *words):
        k, v = self.t[self.i]
        return k == "id" and v.upper() in words

    def op(self, *ops):
        k, v = self.t[self.i]
        return k == "op" and v in ops

    def next(self):
        tok = self.t[self.i]
        self.i += 1
        return tok

    def expect_op(self, o):
        if not self.op(o):
            raise SQLError("expected %s" % o)
        self.i += 1

    def expect_kw(self, w):
        if not self.kw(w):
            raise SQLError("expected %s" % w)
        self.i += 1

    def parse_select(self):
        self.expect_kw("SELECT")
        items = []
        while True:
            e = self.expr()
            name = None
            if self.kw("AS"):
                self.i += 1
                name = self.next()[1]
            elif self.peek()[0] == "id":
                name = self.next()[1]
            items.append((e, name))
            if self.op(","):
                self.i += 1
                continue
            break
        if self.op(";"):
            self.i += 1
        if self.peek()[0] != "end":
            raise SQLError("unexpected token %r" % (self.peek(),))
        return items

    def expr(self):
        return self.or_()

    def or_(self):
        l = self.and_()
        while self.kw("OR"):
            self.i += 1
            l = ("or", l, self.and_())
        return l

    def and_(self):
        l = self.not_()
        while self.kw("AND"):
            self.i += 1
            l = ("and", l, self.not_())
        return l

    def not_(self):
        if self.kw("NOT"):
            self.i += 1
            return ("not", self.not_())
        return self.cmp()

    def cmp(self):
        l = self.add()
        while True:
            if self.op(*CMP):
                o = self.next()[1]
                l = ("cmp", "!=" if o == "<>" else o, l, self.add())
            elif self.kw("IS"):
                self.i += 1
                neg = False
                if self.kw("NOT"):
                    self.i += 1
                    neg = True
                self.expect_kw("NULL")
                l = ("isnull", l, neg)
            else:
                neg = False
                save = self.i
                if self.kw("NOT"):
                    self.i += 1
                    neg = True
                if self.kw("BETWEEN"):
                    self.i += 1
                    a = self.add()
                    self.expect_kw("AND")
                    b = self.add()
                    l = ("between", l, a, b, neg)
                elif self.kw("IN"):
                    self.i += 1
                    self.expect_op("(")
                    items = []
                    if not self.op(")"):
                        items.append(self.expr())
                        while self.op(","):
                            self.i += 1
                            items.append(self.expr())
                    self.expect_op(")")
                    l = ("in", l, items, neg)
                elif self.kw("LIKE"):
                    self.i += 1
                    l = ("like", l, self.add(), neg)
                else:
                    self.i = save
                    return l

    def add(self):
        l = self.mul()
        while self.op("+", "-"):
            o = self.next()[1]
            l = ("arith", o, l, self.mul())
        return l

    def mul(self):
        l = self.concat()
        while self.op("*", "/", "%"):
            o = self.next()[1]
            l = ("arith", o, l, self.concat())
        return l

    def concat(self):
        l = self.unary()
        while self.op("||"):
            self.i += 1
            l = ("concat", l, self.unary())
        return l

    def unary(self):
        if self.op("-"):
            self.i += 1
            return ("neg", self.unary())
        if self.op("+"):
            self.i += 1
            return self.unary()
        return self.primary()

    def primary(self):
        k, v = self.next()
        if k in ("num", "str"):
            return ("lit", v)
        if k == "op" and v == "(":
            e = self.expr()
            self.expect_op(")")
            return e
        if k == "id":
            u = v.upper()
            if u == "NULL":
                return ("lit", None)
            if u == "CASE":
                return self.case()
            if self.op("("):
                self.i += 1
                args = []
                if not self.op(")"):
                    args.append(self.expr())
                    while self.op(","):
                        self.i += 1
                        args.append(self.expr())
                self.expect_op(")")
                return ("func", u, args)
            return ("col", v)
        raise SQLError("unexpected token %r" % ((k, v),))

    def case(self):
        base = None
        if not self.kw("WHEN"):
            base = self.expr()
        whens = []
        while self.kw("WHEN"):
            self.i += 1
            c = self.expr()
            self.expect_kw("THEN")
            whens.append((c, self.expr()))
        els = None
        if self.kw("ELSE"):
            self.i += 1
            els = self.expr()
        self.expect_kw("END")
        return ("case", base, whens, els)


def truth(v):
    if v is None:
        return None
    if isinstance(v, str):
        m = re.match(r"\s*[-+]?\d+", v)
        return 1 if m and int(m.group().strip()) != 0 else 0
    return 1 if v != 0 else 0


def sortkey(v):
    return (1, v) if isinstance(v, str) else (0, v)


def compare(op, a, b):
    if a is None or b is None:
        return None
    a, b = sortkey(a), sortkey(b)
    return int({"=": a == b, "!=": a != b, "<": a < b, "<=": a <= b,
                ">": a > b, ">=": a >= b}[op])


def to_num(v):
    if isinstance(v, str):
        m = re.match(r"\s*[-+]?\d+", v)
        return int(m.group()) if m else 0
    return v


def text(v):
    return v if isinstance(v, str) else str(v)


def like(s, p):
    rx = "".join(".*" if c == "%" else "." if c == "_" else re.escape(c) for c in p)
    return re.fullmatch(rx, s, re.S | re.I) is not None


def substr(s, start, length=None):
    n = len(s)
    if start < 0:
        start = n + start + 1
    if length is None:
        end = n + 1
    else:
        end = start + length
        if length < 0:
            start, end = end, start
    start = max(start, 1)
    end = min(end, n + 1)
    return s[start - 1:end - 1] if end > start else ""


def ev(e, row=None):
    k = e[0]
    if k == "lit":
        return e[1]
    if k == "neg":
        v = ev(e[1], row)
        return None if v is None else -to_num(v)
    if k == "arith":
        a, b = ev(e[2], row), ev(e[3], row)
        if a is None or b is None:
            return None
        a, b, o = to_num(a), to_num(b), e[1]
        if o == "+":
            return a + b
        if o == "-":
            return a - b
        if o == "*":
            return a * b
        if b == 0:
            return None
        q = abs(a) // abs(b)
        if o == "/":
            return q if (a < 0) == (b < 0) else -q
        r = abs(a) % abs(b)
        return -r if a < 0 else r
    if k == "concat":
        a, b = ev(e[1], row), ev(e[2], row)
        return None if a is None or b is None else text(a) + text(b)
    if k == "cmp":
        return compare(e[1], ev(e[2], row), ev(e[3], row))
    if k == "and":
        a = truth(ev(e[1], row))
        if a == 0:
            return 0
        b = truth(ev(e[2], row))
        if b == 0:
            return 0
        return None if a is None or b is None else 1
    if k == "or":
        a = truth(ev(e[1], row))
        if a == 1:
            return 1
        b = truth(ev(e[2], row))
        if b == 1:
            return 1
        return None if a is None or b is None else 0
    if k == "not":
        a = truth(ev(e[1], row))
        return None if a is None else 1 - a
    if k == "isnull":
        r = ev(e[1], row) is None
        return int(r != e[2])
    if k == "between":
        v, lo, hi = ev(e[1], row), ev(e[2], row), ev(e[3], row)
        a, b = compare(">=", v, lo), compare("<=", v, hi)
        r = ev(("and", ("lit", a), ("lit", b)))
        return r if r is None or not e[4] else 1 - r
    if k == "in":
        v = ev(e[1], row)
        if v is None:
            return None
        res = 0
        for it in e[2]:
            c = compare("=", v, ev(it, row))
            if c == 1:
                res = 1
                break
            if c is None:
                res = None
        return res if res is None or not e[3] else 1 - res
    if k == "like":
        v, p = ev(e[1], row), ev(e[2], row)
        if v is None or p is None:
            return None
        r = int(like(text(v), text(p)))
        return 1 - r if e[3] else r
    if k == "case":
        _, base, whens, els = e
        bv = ev(base, row) if base is not None else None
        for c, r in whens:
            if base is None:
                if truth(ev(c, row)) == 1:
                    return ev(r, row)
            elif compare("=", bv, ev(c, row)) == 1:
                return ev(r, row)
        return ev(els, row) if els is not None else None
    if k == "func":
        return func(e[1], [ev(a, row) for a in e[2]])
    raise SQLError("cannot evaluate %r" % (k,))


def func(name, args):
    n = len(args)
    if name == "COALESCE":
        for a in args:
            if a is not None:
                return a
        return None
    if name == "NULLIF":
        if n != 2:
            raise SQLError("NULLIF takes 2 arguments")
        return None if compare("=", args[0], args[1]) == 1 else args[0]
    if name in ("UPPER", "LOWER", "LENGTH", "ABS") and n != 1:
        raise SQLError("wrong number of arguments to %s" % name)
    if not args or args[0] is None:
        if name == "SUBSTR" and not args:
            raise SQLError("wrong number of arguments")
        return None
    a = args[0]
    if name == "UPPER":
        return text(a).upper()
    if name == "LOWER":
        return text(a).lower()
    if name == "LENGTH":
        return len(text(a))
    if name == "ABS":
        return abs(to_num(a))
    if name == "SUBSTR":
        if n not in (2, 3):
            raise SQLError("wrong number of arguments to SUBSTR")
        if any(x is None for x in args[1:]):
            return None
        return substr(text(a), to_num(args[1]), to_num(args[2]) if n == 3 else None)
    raise SQLError("no such function: %s" % name)


class Database:
    def __init__(self, tables):
        self.tables = tables

    def query(self, sql):
        items = Parser(tokenize(sql)).parse_select()
