        self.i = 0

    def peek(self):
        return self.t[self.i]

    def kw(self, *words):
        k, v = self.t[self.i]
        return k == "id" and v.upper() in words

    def op(self, *ops):
        k, v = self.t[self.i]
        return k == "op" and v in ops

    def next(self):
        tok = self.t[self.i]
        self.i += 1
        return tok

    def expect_op(self, o):
        if not self.op(o):
            raise SQLError("expected %s" % o)
        self.i += 1

    def expect_kw(self, w):
        if not self.kw(w):
            raise SQLError("expected %s" % w)
        self.i += 1

    def parse_select(self):
        self.expect_kw("SELECT")
        items = []
        while True:
            e = self.expr()
            name = None
            if self.kw("AS"):
                self.i += 1
                name = self.next()[1]
            elif self.peek()[0] == "id":
                name = self.next()[1]
            items.append((e, name))
            if self.op(","):
                self.i += 1
                continue
            break
        if self.op(";"):
            self.i += 1
        if self.peek()[0] != "end":
            raise SQLError("unexpected token %r" % (self.peek(),))
        return items

    def expr(self):
        return self.or_()

    def or_(self):
        l = self.and_()
        while self.kw("OR"):
            self.i += 1
            l = ("or", l, self.and_())
        return l

    def and_(self):
        l = self.not_()
        while self.kw("AND"):
            self.i += 1
            l = ("and", l, self.not_())
        return l

    def not_(self):
        if self.kw("NOT"):
            self.i += 1
            return ("not", self.not_())
        return self.cmp()
