import functools
from .scope import Scope, okey


class Database:
    def __init__(self, tables):
        self.tables = {k.lower(): v for k, v in tables.items()}

    def source(self, ref):
        if ref is None:
            return [], [()]
        name, alias = ref
        if name.lower() not in self.tables:
            raise SQLError("no such table: %s" % name)
        cols, rows = self.tables[name.lower()]
        return [(alias, c) for c in cols], rows

    def expand_items(self, q, cols):
        items = []
        for e, name in q["items"]:
            if e[0] != "star":
                items.append((e, name))
                continue
            n = len(items)
            for t, c in cols:
                if e[1] is None or t.lower() == e[1].lower():
                    items.append((("col", c, t), c))
            if len(items) == n:
                raise SQLError("no such table: %s" % e[1])
        return items

    def query(self, sql):
        q = Parser(tokenize(sql)).parse_select()
        cols, rows = self.source(q["table"])
        scopes = [Scope(cols, tuple(r)) for r in rows]
        if q["where"] is not None:
            scopes = [s for s in scopes if truth(ev(q["where"], s)) == 1]
        items = self.expand_items(q, cols)
        out = []
        for s in scopes:
            vals = tuple(ev(e, s) for e, _ in items)
            keys = [self.order_value(t, items, vals, s) for t, _ in q["order"]]
            out.append((vals, keys))
        if q["distinct"]:
            seen, uniq = set(), []
            for o in out:
                if o[0] not in seen:
                    seen.add(o[0])
                    uniq.append(o)
            out = uniq
        for i in reversed(range(len(q["order"]))):
            out.sort(key=lambda o: okey(o[1][i]), reverse=q["order"][i][1])
        res = [v for v, _ in out]
        off = ev(q["offset"]) if q["offset"] is not None else 0
        lim = ev(q["limit"]) if q["limit"] is not None else None
        if lim is not None and lim < 0:
            lim = None
        off = max(off or 0, 0)
        return res[off:] if lim is None else res[off:off + lim]

    def order_value(self, t, items, vals, scope):
        if t[0] == "lit" and isinstance(t[1], int):
            if not 1 <= t[1] <= len(items):
                raise SQLError("ORDER BY term out of range")
            return vals[t[1] - 1]
        if t[0] == "col" and t[2] is None:
            for (e, name), v in zip(items, vals):
                if name is not None and name.lower() == t[1].lower():
                    return v
        return ev(t, scope)
