import functools
from .parser import SQLError
from .scope import Scope, okey


def dedup(rows):
    return list(dict.fromkeys(rows))


def combine(op, left, right):
    if op == "union all":
        return left + right
    if op == "union":
        return dedup(left + right)
    other = set(right)
    if op == "intersect":
        return dedup([r for r in left if r in other])
    return dedup([r for r in left if r not in other])


class SetOps:
    def run_setop(self, q, outer):
        from .engine import ev
        parts, ops = q["setop"]
        names, rows = self.run(parts[0], outer)
        for op, part in zip(ops, parts[1:]):
            n2, r2 = self.run(part, outer)
            if len(n2) != len(names):
                raise SQLError("SELECTs to the left and right of %s do not "
                               "have the same number of result columns" % op.upper())
            rows = combine(op, rows, r2)
        cols = [(None, n) for n in names]
        for term, desc in reversed(q["order"]):
            if term[0] == "lit" and isinstance(term[1], int):
                if not 1 <= term[1] <= len(names):
                    raise SQLError("ORDER BY term out of range")
                idx = term[1] - 1
                keyf = lambda r, idx=idx: okey(r[idx])
            else:
                keyf = lambda r, term=term: okey(ev(term, Scope(cols, r, outer)))
            rows = sorted(rows, key=keyf, reverse=desc)
        off = ev(q["offset"], outer) if q["offset"] is not None else 0
        lim = ev(q["limit"], outer) if q["limit"] is not None else None
        if lim is not None and lim < 0:
            lim = None
        off = max(off or 0, 0)
        rows = rows[off:] if lim is None else rows[off:off + lim]
        return names, rows

    def run_recursive(self, name, ccols, cq, outer):
        parts, ops = cq["setop"]
        key = name.lower()
        names, rows = self.run(parts[0], outer)
        names = ccols or names
        union_all = ops[0] == "union all"
        if not union_all:
            rows = dedup(rows)
        result, seen, work = list(rows), set(rows), list(rows)
        while work:
            outer.ctes[key] = (names, work)
            new = []
            for part in parts[1:]:
                new += self.run(part, outer)[1]
            if not union_all:
                new = [r for r in dedup(new) if r not in seen]
                seen.update(new)
            result += new
            work = new
        return names, result
