from .parser import SQLError
from .scope import GroupScope, okey


def collect_windows(e, out):
    if isinstance(e, tuple):
        if e and e[0] == "win":
            if all(w is not e for w in out):
                out.append(e)
            return
        for x in e:
            collect_windows(x, out)
    elif isinstance(e, list):
        for x in e:
            collect_windows(x, out)


def compute_windows(wins, scopes):
    for s in scopes:
        s.win = {}
    for node in wins:
        vals = window_values(node, scopes)
        for s, v in zip(scopes, vals):
            s.win[id(node)] = v


def window_values(node, scopes):
    from .engine import ev
    _, name, args, (part, order, frame) = node
    out = [None] * len(scopes)
    parts = {}
    for i, s in enumerate(scopes):
        parts.setdefault(tuple(ev(p, s) for p in part), []).append(i)
    for idxs in parts.values():
        keys = {i: tuple(okey(ev(t, scopes[i])) for t, _ in order) for i in idxs}
        for k in reversed(range(len(order))):
            idxs = sorted(idxs, key=lambda i: keys[i][k], reverse=order[k][1])
        m = len(idxs)
        first, last, dense = {}, {}, {}
        for pos, i in enumerate(idxs):
            kk = keys[i]
            first.setdefault(kk, pos)
            dense.setdefault(kk, len(dense) + 1)
            last[kk] = pos
        for pos, i in enumerate(idxs):
            s = scopes[i]
            kk = keys[i]
            if name == "ROW_NUMBER":
                v = pos + 1
            elif name == "RANK":
                v = first[kk] + 1
            elif name == "DENSE_RANK":
                v = dense[kk]
            elif name == "NTILE":
                n = ev(args[0], s)
                base, rem = divmod(m, n)
                big = rem * (base + 1)
                v = pos // (base + 1) + 1 if pos < big else rem + (pos - big) // base + 1
            elif name in ("LAG", "LEAD"):
                off = ev(args[1], s) if len(args) > 1 else 1
                tgt = pos - off if name == "LAG" else pos + off
                if 0 <= tgt < m:
                    v = ev(args[0], scopes[idxs[tgt]])
                else:
                    v = ev(args[2], s) if len(args) > 2 else None
            else:
                lo, hi = frame_range(frame, order, pos, m, last[kk], s, ev)
                rows = [scopes[idxs[j]] for j in range(lo, hi + 1)]
                v = frame_value(name, args, rows, ev)
            out[i] = v
    return out


def frame_range(frame, order, pos, m, peer_last, s, ev):
    if frame is None:
        return 0, (peer_last if order else m - 1)

    def edge(b):
        if b[0] == "unb_p":
            return 0
        if b[0] == "unb_f":
            return m - 1
        if b[0] == "cur":
            return pos
        n = ev(b[1], s)
        return pos - n if b[0] == "p" else pos + n
    lo, hi = edge(frame[0]), edge(frame[1])
    return max(lo, 0), min(hi, m - 1)


def frame_value(name, args, rows, ev):
    if name == "COUNT" and not args:
        return len(rows)
    if name in ("FIRST_VALUE", "LAST_VALUE"):
        if not rows:
            return None
        return ev(args[0], rows[0] if name == "FIRST_VALUE" else rows[-1])
    if name not in ("SUM", "COUNT", "MIN", "MAX"):
        raise SQLError("no such window function: %s" % name)
    if not rows:
        return 0 if name == "COUNT" else None
    return GroupScope(rows, None).aggregate(("agg", name, args[0], False), ev)
