import re

KEYWORDS = {"SELECT", "AS", "AND", "OR", "NOT", "IS", "NULL", "IN", "LIKE", "BETWEEN",
            "CASE", "WHEN", "THEN", "ELSE", "END"}


class SQLError(Exception):
    pass


def read_string(sql, i):
    j, buf = i + 1, []
    while True:
        if j >= len(sql):
            raise SQLError("unterminated string")
        if sql[j] == "'":
            if sql[j + 1:j + 2] == "'":
                buf.append("'")
                j += 2
                continue
            return "".join(buf), j + 1
        buf.append(sql[j])
        j += 1


def tokenize(sql):
    toks = []
    i, n = 0, len(sql)
    while i < n:
        c = sql[i]
        if c.isspace():
            i += 1
        elif c == "'":
            s, i = read_string(sql, i)
            toks.append(("str", s))
        elif c.isdigit():
            m = re.compile(r"\d+").match(sql, i)
            toks.append(("num", int(m.group())))
            i = m.end()
        elif c.isalpha() or c == "_":
            m = re.compile(r"\w+").match(sql, i)
            w = m.group()
            toks.append(("kw", w.upper()) if w.upper() in KEYWORDS else ("id", w))
            i = m.end()
        elif sql[i:i + 2] in ("||", "<=", ">=", "!=", "<>", "=="):
            toks.append(("op", sql[i:i + 2]))
            i += 2
        elif c in "+-*/%<>=(),;":
            toks.append(("op", c))
            i += 1
        else:
            raise SQLError("unexpected character %r" % c)
    toks.append(("eof", None))
    return toks
