from .lexer import SQLError

CMP_OPS = ("=", "==", "!=", "<>", "<", "<=", ">", ">=")


class ExprMixin:
    def expr(self):
        l = self.and_()
        while self.accept("kw", "OR"):
            l = ("or", l, self.and_())
        return l

    def and_(self):
        l = self.not_()
        while self.accept("kw", "AND"):
            l = ("and", l, self.not_())
        return l

    def not_(self):
        if self.accept("kw", "NOT"):
            return ("not", self.not_())
        return self.cmp()

    def cmp(self):
        l = self.add()
        while True:
            if self.is_("op") and self.peek()[1] in CMP_OPS:
                op = self.next()[1]
                l = ("cmp", op, l, self.add())
            elif self.accept("kw", "IS"):
                neg = bool(self.accept("kw", "NOT"))
                self.expect("kw", "NULL")
                l = ("isnull", l, neg)
            else:
                save = self.p
                neg = bool(self.accept("kw", "NOT"))
                if self.accept("kw", "BETWEEN"):
                    a = self.add()
                    self.expect("kw", "AND")
                    l = ("between", l, a, self.add(), neg)
                elif self.accept("kw", "IN"):
                    self.expect("op", "(")
                    items = [self.expr()]
                    while self.accept("op", ","):
                        items.append(self.expr())
                    self.expect("op", ")")
                    l = ("in", l, items, neg)
                elif self.accept("kw", "LIKE"):
                    l = ("like", l, self.add(), neg)
                else:
                    self.p = save
                    return l

    def binary(self, ops, sub, tag):
        l = sub()
        while self.is_("op") and self.peek()[1] in ops:
            op = self.next()[1]
            l = (tag, op, l, sub())
        return l

    def add(self):
        return self.binary(("+", "-"), self.mul, "arith")

    def mul(self):
        return self.binary(("*", "/", "%"), self.concat, "arith")

    def concat(self):
        l = self.unary()
        while self.accept("op", "||"):
            l = ("concat", l, self.unary())
        return l

    def unary(self):
        if self.accept("op", "-"):
            return ("neg", self.unary())
        if self.accept("op", "+"):
            return self.unary()
        return self.primary()

    def arglist(self):
        args = []
        if not self.is_("op", ")"):
            args.append(self.expr())
            while self.accept("op", ","):
                args.append(self.expr())
        self.expect("op", ")")
        return args

    def case(self):
        operand = None if self.is_("kw", "WHEN") else self.expr()
        whens = []
        while self.accept("kw", "WHEN"):
            c = self.expr()
            self.expect("kw", "THEN")
            whens.append((c, self.expr()))
        els = self.expr() if self.accept("kw", "ELSE") else None
        self.expect("kw", "END")
        return ("case", operand, whens, els)

    def primary(self):
        k, v = self.next()
        if k in ("num", "str"):
            return ("lit", v)
        if k == "kw" and v == "NULL":
            return ("lit", None)
        if k == "op" and v == "(":
            e = self.expr()
            self.expect("op", ")")
            return e
        if k == "kw" and v == "CASE":
            return self.case()
        if k == "id" and self.accept("op", "("):
            return ("func", v.upper(), self.arglist())
        raise SQLError("unexpected token %r" % (v,))
