from .evalutil import CMP, eval_case, eval_in, tri_or
from .functions import call
from .lexer import SQLError
from .parser import Parser
from .values import (arith, compare, like_match, negate, to_num, to_text,
                     tri_and, truth)


def evaluate(e, row=None):
    op = e[0]
    ev = lambda x: evaluate(x, row)
    if op == "lit":
        return e[1]
    if op == "neg":
        v = ev(e[1])
        return None if v is None else -to_num(v)
    if op == "arith":
        return arith(e[1], ev(e[2]), ev(e[3]))
    if op == "concat":
        a, b = ev(e[1]), ev(e[2])
        return None if a is None or b is None else to_text(a) + to_text(b)
    if op == "cmp":
        a, b = ev(e[2]), ev(e[3])
        if a is None or b is None:
            return None
        return int(CMP[e[1]](compare(a, b)))
    if op == "and":
        a = truth(ev(e[1]))
        return 0 if a == 0 else tri_and(a, truth(ev(e[2])))
    if op == "or":
        a = truth(ev(e[1]))
        return 1 if a == 1 else tri_or(a, truth(ev(e[2])))
    if op == "not":
        return negate(truth(ev(e[1])), True)
    if op == "isnull":
        return int((ev(e[1]) is None) != e[2])
    if op == "between":
        x, a, b = ev(e[1]), ev(e[2]), ev(e[3])
        r1 = None if x is None or a is None else int(compare(x, a) >= 0)
        r2 = None if x is None or b is None else int(compare(x, b) <= 0)
        return negate(tri_and(r1, r2), e[4])
    if op == "in":
        return eval_in(ev(e[1]), [ev(i) for i in e[2]], e[3])
    if op == "like":
        a, b = ev(e[1]), ev(e[2])
        if a is None or b is None:
            return None
        return negate(int(like_match(to_text(a), to_text(b))), e[3])
    if op == "case":
        return eval_case(e, ev)
    if op == "func":
        return call(e[1], [ev(a) for a in e[2]])
    raise SQLError("bad expression")


