from .lexer import SQLError
from .scope import Scope
from .values import compare, to_num


def has_agg(e):
    if isinstance(e, tuple):
        return e[:1] == ("agg",) or any(has_agg(x) for x in e)
    if isinstance(e, list):
        return any(has_agg(x) for x in e)
    return False


def pick(vals, fn):
    best = vals[0]
    for v in vals[1:]:
        if fn(compare(v, best)):
            best = v
    return best


def compute(name, vals, distinct, count_star):
    if count_star:
        return len(vals)
    vals = [v for v in vals if v is not None]
    if distinct:
        vals = list(dict.fromkeys(vals))
    if name == "COUNT":
        return len(vals)
    if not vals:
        return None
    if name == "SUM":
        return sum(to_num(v) for v in vals)
    if name == "MIN":
        return pick(vals, lambda c: c < 0)
    if name == "MAX":
        return pick(vals, lambda c: c > 0)
    raise SQLError("unknown aggregate " + name)


class GroupScope(Scope):
    """A scope over a group of rows; plain columns come from the first row."""

    def __init__(self, cols, scopes):
        first = scopes[0].vals if scopes else (None,) * len(cols)
        Scope.__init__(self, cols, first)
        self.scopes = scopes

    def aggregate(self, e):
        _, name, arg, distinct = e
        if arg is None:
            return compute(name, self.scopes, False, True)
        return compute(name, [evaluate(arg, s) for s in self.scopes], distinct, False)


