from .lexer import SQLError


class Ctx:
    """Per-query context: the database and the visible WITH tables."""

    def __init__(self, db, ctes=None):
        self.db = db
        self.ctes = ctes or {}


class Scope:
    def __init__(self, cols, vals, ctx, outer=None):
        self.cols, self.vals, self.ctx, self.outer = cols, vals, ctx, outer

    def get(self, qual, name):
        n = name.lower()
        q = qual.lower() if qual else None
        hits = [i for i, (cq, cn) in enumerate(self.cols)
                if cn.lower() == n and (q is None or cq.lower() == q)]
        if len(hits) > 1:
            raise SQLError("ambiguous column name: %s" % name)
        if hits:
            return self.vals[hits[0]]
        if self.outer is not None:
            return self.outer.get(qual, name)
        raise SQLError("no such column: %s" % name)


def table_data(ctx, ref, outer=None):
    from .select import run_query
    name, alias = ref
    if isinstance(name, dict):
        names, rows = run_query(ctx, name, outer)
        return [(alias, c) for c in names], rows
    low = name.lower()
    for tn, (cn, rows) in list(ctx.ctes.items()) + list(ctx.db.tables.items()):
        if tn.lower() == low:
            return [(alias, c) for c in cn], rows
    raise SQLError("no such table: %s" % name)


def source_rows(ctx, q, outer=None):
    if q["from"] is None:
        return [], [()]
    from .joins import join_all
    return join_all(ctx, q["from"], outer)


def expand_items(items, cols):
    out = []
    for e, name in items:
        if e[0] == "star":
            idx = [i for i, (cq, _) in enumerate(cols)
                   if e[1] is None or cq.lower() == e[1].lower()]
            if not idx and e[1] is not None:
                raise SQLError("no such table: %s" % e[1])
            out += [(("colidx", i), cols[i][1]) for i in idx]
        else:
            out.append((e, name))
    return out
