from functools import cmp_to_key

from .engine import evaluate
from .lexer import SQLError
from .select import cmp_keys, run_query
from .scope import Ctx


def uniq(rows):
    return list(dict.fromkeys(rows))


def combine(op, left, right):
    if op == "union all":
        return left + right
    if op == "union":
        return uniq(left + right)
    rs = set(right)
    if op == "intersect":
        return uniq([r for r in left if r in rs])
    if op == "except":
        return uniq([r for r in left if r not in rs])
    raise SQLError("unknown set operation " + op)


def sort_key(q, names, row):
    key = []
    for e, desc in q["order"]:
        if e[0] == "lit" and isinstance(e[1], int) and 1 <= e[1] <= len(row):
            v = row[e[1] - 1]
        elif e[0] == "col" and e[1] is None and e[2].lower() in names:
            v = row[names.index(e[2].lower())]
        else:
            raise SQLError("ORDER BY term does not match a result column")
        key.append((v, desc))
    return key


def run_compound(ctx, q, outer):
    names, rows = run_query(ctx, q["compound"][0][1], outer)
    for op, part in q["compound"][1:]:
        rows = combine(op, rows, run_query(ctx, part, outer)[1])
    if q["order"]:
        low = [n.lower() for n in names]
        keyed = [(sort_key(q, low, r), r) for r in rows]
        keyed.sort(key=cmp_to_key(lambda a, b: cmp_keys(a[0], b[0])))
        rows = [r for _, r in keyed]
    off = evaluate(q["offset"]) if q["offset"] is not None else 0
    if q["limit"] is not None:
        lim = evaluate(q["limit"])
        rows = rows[off:off + lim] if lim >= 0 else rows[off:]
    else:
        rows = rows[off:]
    return names, rows


def run_recursive(ctx, name, cols, sub):
    (_, seed), (op, step) = sub["compound"][0], sub["compound"][1]
    names, rows = run_query(ctx, seed, None)
    names = cols or names
    if op == "union":
        rows = uniq(rows)
    seen, delta, out = set(rows), rows, list(rows)
    while delta:
        ctx.ctes[name] = (names, delta)
        new = run_query(ctx, step, None)[1]
        if op == "union":
            new = [r for r in uniq(new) if r not in seen]
            seen.update(new)
        out += new
        delta = new
    return names, out
