    (_, seed), (op, step) = sub["compound"][0], sub["compound"][1]
    names, rows = run_query(ctx, seed, None)
    names = cols or names
    if op == "union":
        rows = uniq(rows)
    seen, delta, out = set(rows), rows, list(rows)
    while delta:
