def tokenize(sql):
    toks = []
    i, n = 0, len(sql)
    while i < n:
        c = sql[i]
        if c.isspace():
            i += 1
        elif c == "'":
            j = i + 1
            buf = []
            while True:
                if j >= n:
                    raise SQLError("unterminated string")
                if sql[j] == "'":
                    if j + 1 < n and sql[j + 1] == "'":
                        buf.append("'")
                        j += 2
                        continue
                    break
                buf.append(sql[j])
                j += 1
            toks.append(("str", "".join(buf)))
            i = j + 1
        elif c.isdigit():
            m = re.compile(r"\d+").match(sql, i)
            toks.append(("num", int(m.group())))
            i = m.end()
