from .lexer import SQLError, tokenize
from .parser_expr import ExprMixin


class Parser(ExprMixin):
    def __init__(self, sql):
        self.t = tokenize(sql)
        self.p = 0

    def peek(self):
        return self.t[self.p]

    def next(self):
        tok = self.t[self.p]
        self.p += 1
        return tok

    def is_(self, kind, val=None):
        k, v = self.peek()
        return k == kind and (val is None or v == val)

    def accept(self, kind, val=None):
        return self.next() if self.is_(kind, val) else None

    def expect(self, kind, val=None):
        if not self.is_(kind, val):
            raise SQLError("expected %s, got %r" % (val or kind, self.peek()[1]))
        return self.next()

    def parse_select(self):
        self.expect("kw", "SELECT")
        items = []
        while True:
            e = self.expr()
            name = None
            if self.accept("kw", "AS"):
                name = self.next()[1]
            elif self.is_("id"):
                name = self.next()[1]
            items.append((e, name))
            if not self.accept("op", ","):
                break
        self.accept("op", ";")
        self.expect("eof")
        return items
