CMP_OPS = ("=", "==", "!=", "<>", "<", "<=", ">", ">=")


class ExprMixin:
    def expr(self):
        l = self.and_()
        while self.accept("kw", "OR"):
            l = ("or", l, self.and_())
        return l

    def and_(self):
        l = self.not_()
        while self.accept("kw", "AND"):
            l = ("and", l, self.not_())
        return l

    def not_(self):
        if self.accept("kw", "NOT"):
            return ("not", self.not_())
        return self.cmp()

    def cmp(self):
        l = self.add()
        while True:
            if self.is_("op") and self.peek()[1] in CMP_OPS:
                op = self.next()[1]
                l = ("cmp", op, l, self.add())
            elif self.accept("kw", "IS"):
                neg = bool(self.accept("kw", "NOT"))
                self.expect("kw", "NULL")
                l = ("isnull", l, neg)
            else:
                save = self.p
                neg = bool(self.accept("kw", "NOT"))
                if self.accept("kw", "BETWEEN"):
                    a = self.add()
                    self.expect("kw", "AND")
                    l = ("between", l, a, self.add(), neg)
                elif self.accept("kw", "IN"):
                    self.expect("op", "(")
                    items = [self.expr()]
                    while self.accept("op", ","):
                        items.append(self.expr())
                    self.expect("op", ")")
                    l = ("in", l, items, neg)
                elif self.accept("kw", "LIKE"):
                    l = ("like", l, self.add(), neg)
                else:
                    self.p = save
                    return l

