        whens = []
        while self.accept("kw", "WHEN"):
            c = self.expr()
            self.expect("kw", "THEN")
            whens.append((c, self.expr()))
        els = self.expr() if self.accept("kw", "ELSE") else None
        self.expect("kw", "END")
        return ("case", operand, whens, els)

