import re


def to_num(v):
    if isinstance(v, str):
        m = re.match(r"\s*[+-]?\d+", v)
        return int(m.group()) if m else 0
    return v


def to_text(v):
    return v if isinstance(v, str) else str(v)


def truth(v):
    return None if v is None else (1 if to_num(v) != 0 else 0)


def compare(a, b):
    ra, rb = isinstance(a, str), isinstance(b, str)
    if ra != rb:
        return -1 if ra < rb else 1
    return (a > b) - (a < b)


def like_match(s, pat):
    rx = "".join(".*" if c == "%" else "." if c == "_" else re.escape(c) for c in pat)
    return re.fullmatch(rx, s, re.S | re.I) is not None


def arith(o, a, b):
    if a is None or b is None:
        return None
    a, b = to_num(a), to_num(b)
    if o == "+":
        return a + b
    if o == "-":
        return a - b
    if o == "*":
        return a * b
    if b == 0:
        return None
    if o == "/":
        q = abs(a) // abs(b)
        return q if (a < 0) == (b < 0) else -q
    r = abs(a) % abs(b)
    return -r if a < 0 else r


def tri_and(a, b):
    if a == 0 or b == 0:
        return 0
    return None if a is None or b is None else 1


def negate(r, neg):
    return r if r is None or not neg else 1 - r
