from .lexer import SQLError
from .values import compare, to_num, to_text


def substr(s, start, ln=None):
    if ln is None:
        lo, hi = start, len(s) + 1
    elif ln < 0:
        lo, hi = start + ln, start
    else:
        lo, hi = start, start + ln
    lo, hi = max(lo, 1), max(hi, 1)
    return s[lo - 1:hi - 1]


def call(name, args):
    if name == "COALESCE":
        return next((a for a in args if a is not None), None)
    if name == "NULLIF":
        a, b = args
        return None if a is not None and b is not None and compare(a, b) == 0 else a
    if not args or args[0] is None:
        return None
    a = args[0]
    if name == "UPPER":
        return to_text(a).upper()
    if name == "LOWER":
        return to_text(a).lower()
    if name == "LENGTH":
        return len(to_text(a))
    if name == "ABS":
        return abs(to_num(a))
    if name == "SUBSTR":
        if any(x is None for x in args[1:]):
            return None
        return substr(to_text(a), *[to_num(x) for x in args[1:]])
    raise SQLError("unknown function %s" % name)
