from .lexer import SQLError

CMP_OPS = ("=", "==", "!=", "<>", "<", "<=", ">", ">=")


class ExprMixin:
    def expr(self):
        l = self.and_()
        while self.accept("kw", "OR"):
            l = ("or", l, self.and_())
        return l

    def and_(self):
        l = self.not_()
        while self.accept("kw", "AND"):
            l = ("and", l, self.not_())
        return l

    def not_(self):
        if self.accept("kw", "NOT"):
            return ("not", self.not_())
        return self.cmp()

    def cmp(self):
        l = self.add()
        while True:
            if self.is_("op") and self.peek()[1] in CMP_OPS:
                op = self.next()[1]
                l = ("cmp", op, l, self.add())
            elif self.accept("kw", "IS"):
                neg = bool(self.accept("kw", "NOT"))
                self.expect("kw", "NULL")
                l = ("isnull", l, neg)
            else:
                save = self.p
                neg = bool(self.accept("kw", "NOT"))
                nl = self.postfix(l, neg)
                if nl is None:
                    self.p = save
                    return l
                l = nl

    def postfix(self, l, neg):
        if self.accept("kw", "BETWEEN"):
            a = self.add()
            self.expect("kw", "AND")
            return ("between", l, a, self.add(), neg)
        if self.accept("kw", "IN"):
            self.expect("op", "(")
            return ("in", l, self.arglist(), neg)
        if self.accept("kw", "LIKE"):
            return ("like", l, self.add(), neg)
        return None
