class ArithMixin:
    def binary(self, ops, sub, tag):
        l = sub()
        while self.is_("op") and self.peek()[1] in ops:
            op = self.next()[1]
            l = (tag, op, l, sub())
        return l

    def add(self):
        return self.binary(("+", "-"), self.mul, "arith")

    def mul(self):
        return self.binary(("*", "/", "%"), self.concat, "arith")

    def concat(self):
        l = self.unary()
        while self.accept("op", "||"):
            l = ("concat", l, self.unary())
        return l

    def unary(self):
        if self.accept("op", "-"):
            return ("neg", self.unary())
        if self.accept("op", "+"):
            return self.unary()
        return self.primary()
