from .engine import evaluate
from .lexer import SQLError
from .values import truth, compare
from functools import cmp_to_key


class Scope:
    def __init__(self, cols, vals):
        self.cols, self.vals = cols, vals

    def get(self, qual, name):
        n = name.lower()
        q = qual.lower() if qual else None
        hits = [i for i, (cq, cn) in enumerate(self.cols)
                if cn.lower() == n and (q is None or cq.lower() == q)]
        if not hits:
            raise SQLError("no such column: %s" % name)
        if len(hits) > 1:
            raise SQLError("ambiguous column name: %s" % name)
        return self.vals[hits[0]]


def source_rows(db, q):
    if q["from"] is None:
        return [], [()]
    name, alias = q["from"]
    for tn, (cn, rows) in db.tables.items():
        if tn.lower() == name.lower():
            return [(alias, c) for c in cn], rows
    raise SQLError("no such table: %s" % name)


def expand_items(items, cols):
    out = []
    for e, name in items:
        if e[0] == "star":
            idx = [i for i, (cq, _) in enumerate(cols)
                   if e[1] is None or cq.lower() == e[1].lower()]
            if not idx and e[1] is not None:
                raise SQLError("no such table: %s" % e[1])
            out += [(("colidx", i), cols[i][1]) for i in idx]
        else:
            out.append((e, name))
    return out


def eval_item(e, scope):
    if e[0] == "colidx":
        return scope.vals[e[1]]
    return evaluate(e, scope)


def order_key(order, items, out, scope):
    key = []
    for e, desc in order:
        if e[0] == "lit" and isinstance(e[1], int):
            if not 1 <= e[1] <= len(out):
                raise SQLError("ORDER BY term out of range")
            v = out[e[1] - 1]
        elif e[0] == "col" and e[1] is None and any(
                n and n.lower() == e[2].lower() for _, n in items):
            v = next(out[i] for i, (_, n) in enumerate(items)
                     if n and n.lower() == e[2].lower())
        else:
            v = evaluate(e, scope)
        key.append((v, desc))
    return key


def cmp_keys(a, b):
    for (x, desc), (y, _) in zip(a, b):
        if x is None and y is None:
            continue
        c = -1 if x is None else 1 if y is None else compare(x, y)
        if c:
            return -c if desc else c
    return 0


def run_select(db, q):
    cols, rows = source_rows(db, q)
    items = expand_items(q["items"], cols)
    result = []
    for r in rows:
        scope = Scope(cols, r)
        if q["where"] is not None and truth(evaluate(q["where"], scope)) != 1:
            continue
        out = tuple(eval_item(e, scope) for e, _ in items)
        result.append((out, order_key(q["order"], items, out, scope)))
    if q["distinct"]:
        seen, uniq = set(), []
        for out, k in result:
            if out not in seen:
                seen.add(out)
                uniq.append((out, k))
        result = uniq
    if q["order"]:
        result.sort(key=cmp_to_key(lambda a, b: cmp_keys(a[1], b[1])))
    res = [o for o, _ in result]
    off = evaluate(q["offset"]) if q["offset"] is not None else 0
    if q["limit"] is not None:
        lim = evaluate(q["limit"])
        res = res[off:off + lim] if lim >= 0 else res[off:]
    else:
        res = res[off:]
    return res
