from .engine import evaluate
from .lexer import SQLError
from .scope import Scope
from .values import compare, to_num


def has_agg(e):
    if isinstance(e, tuple):
        return e[:1] == ("agg",) or any(has_agg(x) for x in e)
    if isinstance(e, list):
        return any(has_agg(x) for x in e)
    return False


def pick(vals, fn):
    best = vals[0]
    for v in vals[1:]:
        if fn(compare(v, best)):
            best = v
    return best


def compute(name, vals, distinct, count_star):
    if count_star:
        return len(vals)
    vals = [v for v in vals if v is not None]
    if distinct:
        vals = list(dict.fromkeys(vals))
    if name == "COUNT":
        return len(vals)
    if not vals:
        return None
    if name == "SUM":
        return sum(to_num(v) for v in vals)
    if name == "MIN":
        return pick(vals, lambda c: c < 0)
    if name == "MAX":
