"""Recursive-descent parser. Expression nodes are tuples whose first item is a tag."""
from .errors import SQLError
from .lexer import tokenize

KEYWORDS = {'AND', 'OR', 'NOT', 'IS', 'IN', 'LIKE', 'BETWEEN', 'NULL', 'CASE', 'WHEN',
            'THEN', 'ELSE', 'END', 'AS', 'SELECT', 'FROM'}
# function name -> (min args, max args or None for unlimited)
FUNCTIONS = {'UPPER': (1, 1), 'LOWER': (1, 1), 'LENGTH': (1, 1), 'ABS': (1, 1),
             'SUBSTR': (2, 3), 'COALESCE': (1, None), 'NULLIF': (2, 2)}
COMPARISONS = ('=', '!=', '<>', '<', '<=', '>', '>=')


class Parser:
    def __init__(self, sql):
        self.toks = tokenize(sql)
        self.i = 0

    # --- token helpers -------------------------------------------------
    def peek(self, k=0):
        return self.toks[min(self.i + k, len(self.toks) - 1)]

    def advance(self):
        tok = self.peek()
        if tok[0] != 'eof':
            self.i += 1
        return tok

    def is_kw(self, word, k=0):
        kind, val = self.peek(k)
        return kind == 'ident' and val.upper() == word

    def is_op(self, op, k=0):
        return self.peek(k) == ('op', op)

    def accept_kw(self, word):
        if self.is_kw(word):
            self.advance()
            return True
        return False

    def accept_op(self, op):
        if self.is_op(op):
            self.advance()
            return True
        return False

    def expect_kw(self, word):
        if not self.accept_kw(word):
            self.error()

    def expect_op(self, op):
        if not self.accept_op(op):
            self.error()

    def error(self):
        kind, val = self.peek()
        if kind == 'eof':
            raise SQLError("syntax error: unexpected end of input")
        raise SQLError(f"syntax error near {val!r}")

    def ident(self):
        kind, val = self.peek()
        if kind != 'ident' or val.upper() in KEYWORDS:
            self.error()
        self.advance()
        return val

    # --- statement -----------------------------------------------------
    def parse(self):
        self.expect_kw('SELECT')
        items = [self.select_item()]
        while self.accept_op(','):
            items.append(self.select_item())
        self.accept_op(';')
        if self.peek()[0] != 'eof':
            self.error()
        return items

    def select_item(self):
        expr = self.expr()
        alias = None
        if self.accept_kw('AS'):
            alias = self.ident()
        elif self.peek()[0] == 'ident' and self.peek()[1].upper() not in KEYWORDS:
            alias = self.advance()[1]
        return expr, alias

    # --- expressions, loosest binding first ----------------------------
    def expr(self):
        left = self.and_expr()
        while self.accept_kw('OR'):
            left = ('or', left, self.and_expr())
        return left

    def and_expr(self):
        left = self.not_expr()
        while self.accept_kw('AND'):
            left = ('and', left, self.not_expr())
        return left

    def not_expr(self):
        if self.accept_kw('NOT'):
            return ('not', self.not_expr())
        return self.comparison()

    def comparison(self):
        left = self.additive()
        while True:
            kind, val = self.peek()
            if kind == 'op' and val in COMPARISONS:
                self.advance()
                left = ('cmp', '!=' if val == '<>' else val, left, self.additive())
            elif self.is_kw('IS'):
                self.advance()
                neg = self.accept_kw('NOT')
                self.expect_kw('NULL')
                left = ('isnull', neg, left)
            elif self.is_kw('NOT') and any(self.is_kw(w, 1) for w in ('BETWEEN', 'IN', 'LIKE')):
                self.advance()
                left = self.predicate(left, True)
            elif any(self.is_kw(w) for w in ('BETWEEN', 'IN', 'LIKE')):
                left = self.predicate(left, False)
            else:
                return left

    def predicate(self, left, neg):
        if self.accept_kw('BETWEEN'):
            lo = self.additive()
            self.expect_kw('AND')
            hi = self.additive()
            return ('between', neg, left, lo, hi)
        if self.accept_kw('IN'):
            self.expect_op('(')
            items = [self.expr()]
            while self.accept_op(','):
                items.append(self.expr())
            self.expect_op(')')
            return ('in', neg, left, items)
        self.expect_kw('LIKE')
        return ('like', neg, left, self.additive())

    def binary(self, operand, ops, tag):
        left = operand()
        while self.peek()[0] == 'op' and self.peek()[1] in ops:
            op = self.advance()[1]
            left = (tag, op, left, operand())
        return left

    def additive(self):
        return self.binary(self.multiplicative, ('+', '-'), 'arith')

    def multiplicative(self):
        return self.binary(self.concat, ('*', '/', '%'), 'arith')

    def concat(self):
        return self.binary(self.unary, ('||',), 'concat')

    def unary(self):
        if self.accept_op('-'):
            return ('neg', self.unary())
        if self.accept_op('+'):
            return self.unary()
        return self.primary()
