    def primary(self):
        kind, val = self.peek()
        if kind in ('num', 'str'):
            self.advance()
            return ('lit', val)
        if self.accept_op('('):
            expr = self.expr()
            self.expect_op(')')
            return expr
        if kind != 'ident':
            self.error()
        up = val.upper()
        if up == 'NULL':
            self.advance()
            return ('lit', None)
        if up == 'CASE':
            return self.case()
        if self.is_op('(', 1):
            return self.call()
        if up in KEYWORDS:
            self.error()
        raise SQLError(f"no such column: {val}")

    def case(self):
        self.advance()  # CASE
        base = None if self.is_kw('WHEN') else self.expr()
        whens = []
        while self.accept_kw('WHEN'):
            cond = self.expr()
            self.expect_kw('THEN')
            whens.append((cond, self.expr()))
        if not whens:
            self.error()
        else_ = self.expr() if self.accept_kw('ELSE') else None
        self.expect_kw('END')
        return ('case', base, whens, else_)

    def call(self):
        name = self.advance()[1].upper()
        if name not in FUNCTIONS:
            raise SQLError(f"no such function: {name}")
        self.expect_op('(')
        args = []
        if not self.is_op(')'):
            args.append(self.expr())
            while self.accept_op(','):
                args.append(self.expr())
        self.expect_op(')')
        lo, hi = FUNCTIONS[name]
        if len(args) < lo or (hi is not None and len(args) > hi):
            raise SQLError(f"wrong number of arguments to function {name}()")
        return ('call', name, args)


