"""Expression evaluation and the Database class. NULL is None; results are int, str or None."""
import operator
import re

from .parser import parse


def to_num(v):
    """Numeric value of v, as SQLite does for text: the leading integer, or 0."""
    if v is None or not isinstance(v, str):
        return v
    m = re.match(r'\s*([+-]?\d+)', v)
    return int(m.group(1)) if m else 0


def to_text(v):
    if v is None or isinstance(v, str):
        return v
    return str(v)


def truth(v):
    """True, False, or None (NULL) for a value used as a condition."""
    n = to_num(v)
    return None if n is None else n != 0


def not3(v):
    """Three-valued NOT on a result (int or None)."""
    return None if v is None else int(not v)


def and3(a, b):
    """Three-valued AND on truth values (True, False or None); returns 1, 0 or None."""
    if a is False or b is False:
        return 0
    if a is None or b is None:
        return None
    return 1


def or3(a, b):
    if a is True or b is True:
        return 1
    if a is None or b is None:
        return None
    return 0


def compare(a, b):
    """-1, 0 or 1 for a < b, a = b, a > b; None if either side is NULL.
    Numbers sort before text, as in SQLite."""
    if a is None or b is None:
        return None
    if isinstance(a, str) != isinstance(b, str):
        return 1 if isinstance(a, str) else -1
    return (a > b) - (a < b)


COMPARE_OPS = {'=': operator.eq, '!=': operator.ne, '<': operator.lt,
               '<=': operator.le, '>': operator.gt, '>=': operator.ge}


def arith(op, a, b):
    a, b = to_num(a), to_num(b)
    if a is None or b is None:
        return None
    if op == '+':
        return a + b
    if op == '-':
        return a - b
    if op == '*':
        return a * b
    if b == 0:
        return None
    if op == '/':
        q = abs(a) // abs(b)  # truncate toward zero
        return q if (a < 0) == (b < 0) else -q
    r = abs(a) % abs(b)  # '%' takes the sign of the left operand
    return -r if a < 0 else r


def like(value, pattern):
    """1 or 0 for SQL LIKE; ASCII case-insensitive."""
    parts = []
    for ch in pattern:
        if ch == '%':
            parts.append('.*')
        elif ch == '_':
            parts.append('.')
        else:
            parts.append(re.escape(ch))
    return int(re.fullmatch(''.join(parts), value, re.DOTALL | re.IGNORECASE) is not None)


def substr(s, start, length=None):
    """SQLite's SUBSTR: 1-based start, negative start counts from the end."""
    n = len(s)
    begin = n + start + 1 if start < 0 else start
    if length is None:
        end = n + 1
    elif length >= 0:
        end = begin + length
    else:
        end = begin
        begin = begin + length
    begin, end = max(begin, 1), min(end, n + 1)
    return s[begin - 1:end - 1] if end > begin else ''
