class Scope:
    """The columns an expression can see: one table row, or nothing (no FROM)."""

    def __init__(self, qualifier=None, columns=(), values=()):
        self.qualifier = qualifier
        self.columns = list(columns)
        self.values = values

    def get(self, qual, name):
        if qual is not None and (self.qualifier is None or qual.lower() != self.qualifier.lower()):
            raise SQLError(f"no such column: {qual}.{name}")
        for i, col in enumerate(self.columns):
            if col.lower() == name.lower():
                return self.values[i]
        raise SQLError(f"no such column: {name}")


def evaluate(node, ctx):
    tag = node[0]
    ev = lambda n: evaluate(n, ctx)  # noqa: E731
    if tag == 'lit':
        return node[1]
    if tag == 'col':
        return ctx.get(node[1], node[2])
    if tag == 'neg':
        v = to_num(ev(node[1]))
        return None if v is None else -v
    if tag == 'arith':
        return arith(node[1], ev(node[2]), ev(node[3]))
    if tag == 'concat':
        a, b = to_text(ev(node[2])), to_text(ev(node[3]))
        return None if a is None or b is None else a + b
    if tag == 'cmp':
        c = compare(ev(node[2]), ev(node[3]))
        return None if c is None else int(COMPARE_OPS[node[1]](c, 0))
    if tag == 'and':
        return and3(truth(ev(node[1])), truth(ev(node[2])))
    if tag == 'or':
        return or3(truth(ev(node[1])), truth(ev(node[2])))
    if tag == 'not':
        return not3(truth(ev(node[1])))
    if tag == 'isnull':
        is_null = ev(node[2]) is None
        return int(not is_null if node[1] else is_null)
