def ntile(p, m, n):
    if n is None or n <= 0:
        return None
    size, rem = divmod(m, n)
    if size == 0:
        return p + 1
    big = rem * (size + 1)
    return p // (size + 1) + 1 if p < big else rem + (p - big) // size + 1


