def call_function(name, args):
    if name == 'COALESCE':
        return next((v for v in args if v is not None), None)
    if name == 'NULLIF':
        a, b = args
        if a is None:
            return None
        return None if compare(a, b) == 0 else a
    if any(v is None for v in args):
        return None
    if name == 'UPPER':
        return to_text(args[0]).upper()
    if name == 'LOWER':
        return to_text(args[0]).lower()
    if name == 'LENGTH':
        return len(to_text(args[0]))
    if name == 'ABS':
        return abs(to_num(args[0]))
    s = to_text(args[0])  # SUBSTR
    start = to_num(args[1])
    length = to_num(args[2]) if len(args) > 2 else None
    return substr(s, start, length)


def in_list(v, items):
    """1 if v equals an item; NULL if v or an item is NULL (and no match); else 0."""
    if v is None:
        return None
    saw_null = False
    for w in items:
        if w is None:
            saw_null = True
        elif compare(v, w) == 0:
            return 1
    return None if saw_null else 0
