def evaluate(node):
    tag = node[0]
    if tag == 'lit':
        return node[1]
    if tag == 'neg':
        v = to_num(evaluate(node[1]))
        return None if v is None else -v
    if tag == 'arith':
        return arith(node[1], evaluate(node[2]), evaluate(node[3]))
    if tag == 'concat':
        a, b = to_text(evaluate(node[2])), to_text(evaluate(node[3]))
        return None if a is None or b is None else a + b
    if tag == 'cmp':
        c = compare(evaluate(node[2]), evaluate(node[3]))
        return None if c is None else int(COMPARE_OPS[node[1]](c, 0))
    if tag == 'and':
        return and3(truth(evaluate(node[1])), truth(evaluate(node[2])))
    if tag == 'or':
        return or3(truth(evaluate(node[1])), truth(evaluate(node[2])))
    if tag == 'not':
        return not3(truth(evaluate(node[1])))
    if tag == 'isnull':
        is_null = evaluate(node[2]) is None
        return int(not is_null if node[1] else is_null)
    if tag == 'between':
        _, neg, x, lo, hi = node
        v = evaluate(x)
        c_lo, c_hi = compare(v, evaluate(lo)), compare(v, evaluate(hi))
        r = and3(None if c_lo is None else c_lo >= 0, None if c_hi is None else c_hi <= 0)
        return not3(r) if neg else r
    if tag == 'in':
        _, neg, x, items = node
        r = in_list(evaluate(x), [evaluate(i) for i in items])
        return not3(r) if neg else r
    if tag == 'like':
        _, neg, x, pat = node
        v, p = to_text(evaluate(x)), to_text(evaluate(pat))
        if v is None or p is None:
            return None
        r = like(v, p)
        return not3(r) if neg else r
    if tag == 'case':
        _, base, whens, else_ = node
        if base is None:
            for cond, val in whens:
                if truth(evaluate(cond)) is True:
                    return evaluate(val)
        else:
            b = evaluate(base)
            for cond, val in whens:
                if b is not None and compare(b, evaluate(cond)) == 0:
                    return evaluate(val)
        return None if else_ is None else evaluate(else_)
    if tag == 'call':
        return call_function(node[1], [evaluate(a) for a in node[2]])
    raise ValueError(f"unknown node {tag}")


class Database:
    def __init__(self, tables):
        self.tables = tables

    def query(self, sql):
        items = parse(sql)
        return [tuple(evaluate(expr) for expr, _alias in items)]
