    def parse(self):
        self.expect_kw('SELECT')
        distinct = self.accept_kw('DISTINCT')
        items = [self.select_item()]
        while self.accept_op(','):
            items.append(self.select_item())
        source = None
        if self.accept_kw('FROM'):
            source = self.table_ref()
        where = self.expr() if self.accept_kw('WHERE') else None
        order = []
        if self.accept_kw('ORDER'):
            self.expect_kw('BY')
            order.append(self.order_term())
            while self.accept_op(','):
                order.append(self.order_term())
        limit = offset = None
        if self.accept_kw('LIMIT'):
            limit = self.expr()
            if self.accept_kw('OFFSET'):
                offset = self.expr()
        self.accept_op(';')
        if self.peek()[0] != 'eof':
            self.error()
        return {'distinct': distinct, 'items': items, 'source': source, 'where': where,
                'order': order, 'limit': limit, 'offset': offset}

    def table_ref(self):
        name = self.ident()
        alias = None
        if self.accept_kw('AS'):
            alias = self.ident()
        elif self.peek()[0] == 'ident' and self.peek()[1].upper() not in KEYWORDS:
            alias = self.advance()[1]
        return name, alias

    def order_term(self):
        expr = self.expr()
        desc = self.accept_kw('DESC')
        if not desc:
            self.accept_kw('ASC')
        return expr, desc

    def select_item(self):
        if self.accept_op('*'):
            return ('star', None), None
        if self.peek()[0] == 'ident' and self.is_op('.', 1) and self.is_op('*', 2):
            qual = self.advance()[1]
            self.advance()
            self.advance()
            return ('star', qual), None
        expr = self.expr()
        alias = None
        if self.accept_kw('AS'):
            alias = self.ident()
        elif self.peek()[0] == 'ident' and self.peek()[1].upper() not in KEYWORDS:
            alias = self.advance()[1]
        return expr, alias

