def run_select(tables, q):
    """Execute a parsed SELECT against the tables and return a list of row tuples."""
    if q['source'] is None:
        if any(n[0] == 'star' for n, _ in q['items']):
            raise SQLError("no tables specified")
        qual, columns, rows = None, [], [()]
    else:
        name, alias = q['source']
        lookup = {k.lower(): v for k, v in tables.items()}
        if name.lower() not in lookup:
            raise SQLError(f"no such table: {name}")
        columns, rows = lookup[name.lower()]
        qual = alias or name
    scopes = [Scope(qual, columns, r) for r in rows]
    if q['where'] is not None:
        scopes = [s for s in scopes if truth(evaluate(q['where'], s)) is True]

    outs = []  # (expression node, explicit alias)
    for node, alias in q['items']:
        if node[0] == 'star':
            if node[1] is not None and node[1].lower() != (qual or '').lower():
                raise SQLError(f"no such table: {node[1]}")
            outs.extend((('col', qual, c), None) for c in columns)
        else:
            outs.append((node, alias))

    # each ORDER BY term: ('out', index) into the select list, or ('expr', node)
    order, descs = [], []
    for expr, desc in q['order']:
        if expr[0] == 'lit' and type(expr[1]) is int:
            if not 1 <= expr[1] <= len(outs):
                raise SQLError("ORDER BY term out of range")
            order.append(('out', expr[1] - 1))
        else:
            idx = None
            if expr[0] == 'col' and expr[1] is None:
                for i, (_, alias) in enumerate(outs):
                    if alias is not None and alias.lower() == expr[2].lower():
                        idx = i
                        break
            order.append(('out', idx) if idx is not None else ('expr', expr))
        descs.append(desc)

    produced = []
    for s in scopes:
        out = tuple(evaluate(n, s) for n, _ in outs)
        keys = tuple(out[v] if kind == 'out' else evaluate(v, s) for kind, v in order)
        produced.append((keys, out))
    if order:
        produced.sort(key=cmp_to_key(lambda a, b: _order_cmp(a[0], b[0], descs)))
    result = [out for _, out in produced]

    if q['distinct']:
        seen, unique = set(), []
        for r in result:
            if r not in seen:
                seen.add(r)
                unique.append(r)
        result = unique

    offset = _const(q['offset']) if q['offset'] is not None else None
    limit = _const(q['limit']) if q['limit'] is not None else None
    result = result[max(offset or 0, 0):]
    if limit is not None and limit >= 0:
        result = result[:limit]
    return result


class Database:
    def __init__(self, tables):
        self.tables = tables

    def query(self, sql):
        return run_select(self.tables, parse(sql))
