def execute(tables, q, outer=None):
    """Run a parsed SELECT. Returns (column names, rows)."""
    if q.get('ctes'):
        tables = dict(tables)
        for name, cols, sub in q['ctes']:
            names, rows = execute(tables, sub)
            tables[name] = (cols or names, rows)
    if q['source'] is None:
        combined, layout = [[]], []
    else:
        combined, layout = join_rows(tables, q['source'], outer)
    scopes = [Scope(parts, outer, tables) for parts in combined]
    if q['where'] is not None:
        scopes = [s for s in scopes if truth(evaluate(q['where'], s)) is True]

    outs = []  # (expression node, explicit alias)
    for node, alias in q['items']:
        if node[0] == 'star':
            matched = [(qual, cols) for qual, cols in layout
                       if node[1] is None or node[1].lower() == (qual or '').lower()]
            if node[1] is not None and not matched:
                raise SQLError(f"no such table: {node[1]}")
            if not layout:
                raise SQLError("no tables specified")
            outs.extend((('col', qual, c), None) for qual, cols in matched for c in cols)
        else:
            outs.append((node, alias))
    names = [alias or (n[2] if n[0] == 'col' else f'column{i + 1}')
             for i, (n, alias) in enumerate(outs)]

    aggregated = bool(q['group']) or q['having'] is not None or any(
        contains_agg(n) for n, _ in outs) or any(contains_agg(e) for e, _ in q['order'])
    if aggregated:
        if q['group']:
            buckets = {}
            for s in scopes:
                buckets.setdefault(tuple(evaluate(g, s) for g in q['group']), []).append(s)
            groups = list(buckets.values())
        else:
            groups = [scopes]  # one group, even when no row matches
        scopes = [group_scope(layout, g, outer, tables) for g in groups]
        if q['having'] is not None:
            scopes = [s for s in scopes if truth(evaluate(q['having'], s)) is True]

