def find_windows(node, acc):
    """Collect the window function nodes of a query (they are not nested)."""
    if isinstance(node, tuple) and node and node[0] == 'win':
        acc.append(node)
    elif isinstance(node, (list, tuple)):
        for x in node:
            find_windows(x, acc)
    return acc


def reduce_values(name, vals):
    """SUM, MIN or MAX over non-NULL values; NULL when there are none."""
    if not vals:
        return None
    if name == 'SUM':
        return sum(to_num(v) for v in vals)
    best = vals[0]
    for v in vals[1:]:
        c = compare(v, best)
        if (name == 'MIN' and c < 0) or (name == 'MAX' and c > 0):
            best = v
    return best


def frame_bound(b, p, m):
    """Position (may be out of range) of a frame bound for the row at position p of m."""
    if b[0] == 'start':
        return 0
    if b[0] == 'end':
        return m - 1
    if b[0] == 'cur':
        return p
    return p - b[1] if b[0] == 'pre' else p + b[1]


def compute_window(node, scopes):
    """Value of one window function for each scope (row or group), in the same order."""
    _, name, args, star, part, order, frame = node
    descs = [d for _, d in order]
    keys = [tuple(evaluate(e, s) for e, _ in order) for s in scopes]
    partitions = {}
    for i, s in enumerate(scopes):
        partitions.setdefault(tuple(evaluate(p, s) for p in part), []).append(i)
    values = [None] * len(scopes)
    for idxs in partitions.values():
        idxs.sort(key=cmp_to_key(lambda a, b: _order_cmp(keys[a], keys[b], descs)))
        m = len(idxs)
        argv = [[evaluate(a, scopes[i]) for a in args] for i in idxs]
        kk = [keys[i] for i in idxs]
        peer_last = list(range(m))  # last position of the peer group (same ORDER BY values)
        for p in range(m - 2, -1, -1):
            if kk[p] == kk[p + 1]:
                peer_last[p] = peer_last[p + 1]
        peer_first = [0] * m
        dense = [0] * m
        for p in range(m):
            same = p > 0 and kk[p] == kk[p - 1]
            peer_first[p] = peer_first[p - 1] if same else p
            dense[p] = dense[p - 1] if same else (dense[p - 1] + 1 if p else 1)
        for p in range(m):
            if frame is not None:
                lo = max(frame_bound(frame[0], p, m), 0)
                hi = min(frame_bound(frame[1], p, m), m - 1)
            elif order:
                lo, hi = 0, peer_last[p]
            else:
                lo, hi = 0, m - 1
            span = range(lo, hi + 1)
            if name == 'ROW_NUMBER':
                v = p + 1
            elif name == 'RANK':
                v = peer_first[p] + 1
            elif name == 'DENSE_RANK':
                v = dense[p]
            elif name == 'NTILE':
                v = ntile(p, m, to_num(argv[p][0]))
            elif name in ('LAG', 'LEAD'):
                off = to_num(argv[p][1]) if len(args) > 1 else 1
                j = p - off if name == 'LAG' else p + off
                if 0 <= j < m:
                    v = argv[j][0]
                else:
                    v = argv[p][2] if len(args) > 2 else None
            elif name == 'FIRST_VALUE':
                v = argv[span.start][0] if len(span) else None
            elif name == 'LAST_VALUE':
                v = argv[span.stop - 1][0] if len(span) else None
            elif name == 'COUNT' and star:
                v = len(span)
            else:
                vals = [argv[j][0] for j in span if argv[j][0] is not None]
                v = len(vals) if name == 'COUNT' else reduce_values(name, vals)
            values[idxs[p]] = v
    return values


def ntile(p, m, n):
    if n is None or n <= 0:
        return None
    size, rem = divmod(m, n)
    if size == 0:
        return p + 1
    big = rem * (size + 1)
    return p // (size + 1) + 1 if p < big else rem + (p - big) // size + 1


