def window_value(name, star, args, frame, order, argv, p, m, peer_first, peer_last, dense):
    """Window function value for the row at position p of a partition of m ordered rows."""
    if frame is not None:
        lo = max(frame_bound(frame[0], p, m), 0)
        hi = min(frame_bound(frame[1], p, m), m - 1)
    elif order:
        lo, hi = 0, peer_last[p]
    else:
        lo, hi = 0, m - 1
    span = range(lo, hi + 1)
    if name == 'ROW_NUMBER':
        return p + 1
    if name == 'RANK':
