# ---- parser ----------------------------------------------------------------

CMP_OPS = {"=", "!=", "<>", "<", "<=", ">", ">="}


class Parser:
    def __init__(self, sql):
        self.toks = tokenize(sql)
        self.pos = 0

    def peek(self, k=0):
        return self.toks[min(self.pos + k, len(self.toks) - 1)]

    def advance(self):
        t = self.toks[self.pos]
        self.pos += 1
        return t

    def is_kw(self, word, k=0):
        t = self.peek(k)
        return t[0] == "kw" and t[1] == word

    def is_op(self, op, k=0):
        t = self.peek(k)
        return t[0] == "op" and t[1] == op

    def accept_kw(self, word):
        if self.is_kw(word):
            self.pos += 1
            return True
        return False

    def accept_op(self, op):
        if self.is_op(op):
            self.pos += 1
            return True
        return False

    def expect_kw(self, word):
        if not self.accept_kw(word):
            raise SQLError(f"expected {word}, got {self.peek()[1]!r}")

    def expect_op(self, op):
        if not self.accept_op(op):
            raise SQLError(f"expected {op!r}, got {self.peek()[1]!r}")

    def parse_query(self):
        self.expect_kw("SELECT")
        items = [self.parse_item()]
        while self.accept_op(","):
            items.append(self.parse_item())
        if self.is_kw("FROM"):
            raise SQLError("FROM is not supported yet")
        self.accept_op(";")
        if self.peek()[0] != "end":
            raise SQLError(f"unexpected token {self.peek()[1]!r}")
        return items

    def parse_item(self):
        e = self.parse_expr()
        alias = None
        if self.accept_kw("AS"):
            t = self.advance()
            if t[0] != "id":
                raise SQLError("expected alias name")
            alias = t[1]
        elif self.peek()[0] == "id":
            alias = self.advance()[1]
        return (e, alias)

    # precedence, loosest first: OR, AND, NOT, comparisons, +-, */%, ||, unary
    def parse_expr(self):
        e = self.parse_and()
        while self.accept_kw("OR"):
            e = ("bin", "OR", e, self.parse_and())
        return e

    def parse_and(self):
        e = self.parse_not()
        while self.accept_kw("AND"):
            e = ("bin", "AND", e, self.parse_not())
        return e

    def parse_not(self):
        if self.accept_kw("NOT"):
            return ("not", self.parse_not())
        return self.parse_cmp()

    def parse_cmp(self):
        e = self.parse_add()
        while True:
            t = self.peek()
            if t[0] == "op" and t[1] in CMP_OPS:
                self.advance()
                e = ("bin", "=" if t[1] == "==" else t[1], e, self.parse_add())
            elif self.is_kw("IS"):
                self.advance()
                neg = self.accept_kw("NOT")
                self.expect_kw("NULL")
                e = ("isnull", e, neg)
            elif self.is_kw("BETWEEN") or self.is_kw("IN") or self.is_kw("LIKE") or (
                    self.is_kw("NOT") and (self.is_kw("BETWEEN", 1) or self.is_kw("IN", 1) or self.is_kw("LIKE", 1))):
                neg = self.accept_kw("NOT")
                if self.accept_kw("BETWEEN"):
                    lo = self.parse_add()
                    self.expect_kw("AND")
                    hi = self.parse_add()
                    e = ("between", e, lo, hi, neg)
                elif self.accept_kw("IN"):
                    self.expect_op("(")
                    items = [self.parse_expr()]
                    while self.accept_op(","):
                        items.append(self.parse_expr())
                    self.expect_op(")")
                    e = ("in", e, items, neg)
                else:
                    self.expect_kw("LIKE")
                    e = ("like", e, self.parse_add(), neg)
            else:
                return e

    def parse_add(self):
        e = self.parse_mul()
        while self.is_op("+") or self.is_op("-"):
            op = self.advance()[1]
            e = ("bin", op, e, self.parse_mul())
        return e

    def parse_mul(self):
        e = self.parse_concat()
        while self.is_op("*") or self.is_op("/") or self.is_op("%"):
            op = self.advance()[1]
            e = ("bin", op, e, self.parse_concat())
        return e

    def parse_concat(self):
        e = self.parse_unary()
        while self.accept_op("||"):
            e = ("bin", "||", e, self.parse_unary())
        return e

    def parse_unary(self):
        if self.accept_op("-"):
            return ("neg", self.parse_unary())
        return self.parse_primary()

    def parse_primary(self):
        t = self.advance()
        if t[0] in ("num", "str"):
            return ("lit", t[1])
        if t[0] == "kw" and t[1] == "NULL":
            return ("lit", None)
        if t[0] == "op" and t[1] == "(":
            e = self.parse_expr()
            self.expect_op(")")
            return e
        if t[0] == "kw" and t[1] == "CASE":
            return self.parse_case()
        if t[0] == "id":
            if not self.accept_op("("):
                raise SQLError(f"no such column: {t[1]}")
            name = t[1].upper()
            args = []
            if not self.accept_op(")"):
                args.append(self.parse_expr())
                while self.accept_op(","):
                    args.append(self.parse_expr())
                self.expect_op(")")
            return ("func", name, args)
        raise SQLError(f"unexpected token {t[1]!r}")

    def parse_case(self):
        base = None
        if not self.is_kw("WHEN"):
            base = self.parse_expr()
        whens = []
        while self.accept_kw("WHEN"):
            c = self.parse_expr()
            self.expect_kw("THEN")
            whens.append((c, self.parse_expr()))
        if not whens:
            raise SQLError("CASE needs WHEN")
        els = self.parse_expr() if self.accept_kw("ELSE") else None
        self.expect_kw("END")
        return ("case", base, whens, els)


def parse(sql):
    return Parser(sql).parse_query()
