    s = parse_select(sql)
    if s.table is None:
        if any(it[0] == "star" for it in s.items):
            raise SQLError("no tables specified")
        envs = [None]
        cols = []
        qual = None
    else:
        lower = {k.lower(): k for k in tables}
        key = lower.get(s.table.lower())
        if key is None:
            raise SQLError(f"no such table: {s.table}")
        cols, rows = tables[key]
        qual = s.alias or s.table
        envs = [Env([(qual, cols, r)]) for r in rows]

    # output column names (star items expand to the table's columns)
    names = []
    for it in s.items:
        if it[0] == "star":
            if it[1] is not None and (qual is None or it[1].lower() != qual.lower()):
                raise SQLError(f"no such table: {it[1]}")
            names.extend(cols)
        else:
