    terms = []
    for node, desc in s.order:
        if node[0] == "lit" and isinstance(node[1], int):
            if not 1 <= node[1] <= len(names):
                raise SQLError("ORDER BY term out of range")
            terms.append((("out", node[1] - 1), desc))
        elif node[0] == "col" and node[1] is None and node[2].lower() in [
                n.lower() for n in names if n is not None]:
            idx = [i for i, n in enumerate(names) if n is not None and n.lower() == node[2].lower()][0]
            terms.append((("out", idx), desc))
        else:
            terms.append((("expr", node), desc))

    produced = []
    for env in envs:
        if s.where is not None and truth(ev(s.where, env)) is not True:
            continue
        out = []
        for it in s.items:
            if it[0] == "star":
                for q, _, r in env.sources:
                    if it[1] is None or it[1].lower() == q.lower():
                        out.extend(r)
            else:
                out.append(ev(it[1], env))
