def _table_ref(p):
    if p.is_op("("):
        p.advance()
        sel = parse_select_p(p)
        p.expect_op(")")
        ref = sel
    else:
        t = p.advance()
        if t[0] != "id":
            raise SQLError("expected table name")
        ref = t[1]
    alias = None
    if p.accept_kw("AS"):
        alias = p.advance()[1]
    elif p.peek()[0] == "id":
        alias = p.advance()[1]
    return ref, alias


def parse_select_p(p):
    """Parse one SELECT from a parser (no end-of-input check; subqueries use this)."""
    s = Select()
    if p.accept_kw("WITH"):
        while True:
            name = p.advance()[1]
            cols = None
            if p.accept_op("("):
                cols = [p.advance()[1]]
                while p.accept_op(","):
                    cols.append(p.advance()[1])
                p.expect_op(")")
            p.expect_kw("AS")
            p.expect_op("(")
            sub = parse_select_p(p)
            p.expect_op(")")
            s.ctes.append((name, cols, sub))
            if not p.accept_op(","):
                break
    p.expect_kw("SELECT")
    s.distinct = p.accept_kw("DISTINCT")
    while True:
        if p.accept_op("*"):
            s.items.append(("star", None))
        elif p.peek()[0] == "id" and p.is_op(".", 1) and p.is_op("*", 2):
            s.items.append(("star", p.advance()[1]))
            p.advance()
            p.advance()
        else:
            e, alias = p.parse_item()
            s.items.append(("expr", e, alias))
        if not p.accept_op(","):
            break
