        while True:
            if p.accept_op(","):
                kind = "cross"
            elif p.accept_kw("CROSS"):
                p.expect_kw("JOIN")
                kind = "cross"
            elif p.accept_kw("LEFT"):
                p.accept_kw("OUTER")
                p.expect_kw("JOIN")
                kind = "left"
            elif p.accept_kw("INNER"):
                p.expect_kw("JOIN")
                kind = "inner"
            elif p.accept_kw("JOIN"):
                kind = "inner"
            else:
