def run_select(s, tables, outer=None):
    """Run a parsed SELECT. Returns (output column names, rows)."""
    if s.ctes:
        local = dict(tables)
        for name, cols, sub in s.ctes:
            names, rows = run_select(sub, local, None)
            local[name] = (cols if cols else names, rows)
