def _aggregate(name, vals, distinct=False):
    vals = [v for v in vals if v is not None]
    if distinct:
        vals = list(dict.fromkeys(vals))
    if name == "COUNT":
        return len(vals)
    if not vals:
        return None
    if name == "SUM":
        return sum(to_num(v) for v in vals)
    best = vals[0]
    for v in vals[1:]:
        c = compare(v, best)
        if (name == "MIN" and c < 0) or (name == "MAX" and c > 0):
            best = v
    return best


def _bound_lo(b, p, m):
    kind = b[0]
    if kind == "unb_p":
        return 0
    if kind == "cur":
        return p
    if kind == "p":
        return p - b[1]
    if kind == "f":
        return p + b[1]
    return m


def _bound_hi(b, p, m):
    kind = b[0]
    if kind == "unb_f":
        return m - 1
    if kind == "cur":
        return p
    if kind == "f":
        return p + b[1]
    if kind == "p":
        return p - b[1]
    return -1
