"""Expression engine for minisql (checkpoint 1)."""
import re


class SQLError(Exception):
    pass


KEYWORDS = {"SELECT", "FROM", "AS", "AND", "OR", "NOT", "IS", "NULL", "BETWEEN",
            "IN", "LIKE", "CASE", "WHEN", "THEN", "ELSE", "END"}
OPS = ["||", "<=", ">=", "<>", "!=", "=", "<", ">", "+", "-", "*", "/", "%", "(", ")", ",", ";"]


def tokenize(sql):
    toks = []  # (kind, value): kind in num, str, id, kw, op, end
    i, n = 0, len(sql)
    while i < n:
        c = sql[i]
        if c.isspace():
            i += 1
        elif c == "'":
            j, buf = i + 1, []
            while True:
                if j >= n:
                    raise SQLError("unterminated string literal")
                if sql[j] == "'":
                    if j + 1 < n and sql[j + 1] == "'":
                        buf.append("'")
                        j += 2
                        continue
                    break
                buf.append(sql[j])
                j += 1
            toks.append(("str", "".join(buf)))
            i = j + 1
        elif c.isdigit():
            m = re.compile(r"\d+").match(sql, i)
            if m.end() < n and (sql[m.end()].isalpha() or sql[m.end()] == "_"):
                raise SQLError("unrecognized token")
            toks.append(("num", int(m.group())))
            i = m.end()
        elif c.isalpha() or c == "_":
            m = re.compile(r"[A-Za-z_][A-Za-z0-9_]*").match(sql, i)
            word = m.group()
            if word.upper() in KEYWORDS:
                toks.append(("kw", word.upper()))
            else:
                toks.append(("id", word))
            i = m.end()
        else:
            for op in OPS:
                if sql.startswith(op, i):
                    toks.append(("op", op))
                    i += len(op)
                    break
            else:
                raise SQLError(f"unrecognized token: {c!r}")
    toks.append(("end", None))
    return toks


# ---- value helpers -------------------------------------------------------

def to_text(v):
    if isinstance(v, str):
        return v
    return str(v)


def to_num(v):
    """Numeric value of a non-NULL value, SQLite style (leading integer prefix of text, else 0)."""
    if isinstance(v, str):
        m = re.match(r"\s*([+-]?\d+)", v)
        return int(m.group(1)) if m else 0
    return v


def truth(v):
    """True, False, or None (NULL)."""
    if v is None:
        return None
    return to_num(v) != 0


def from_truth(t):
    return None if t is None else (1 if t else 0)


def compare(a, b):
    """-1, 0, 1, or None if either side is NULL. Numbers sort before text."""
    if a is None or b is None:
        return None
    a_str, b_str = isinstance(a, str), isinstance(b, str)
    if a_str and b_str:
        return (a > b) - (a < b)
    if a_str != b_str:
        return 1 if a_str else -1
    return (a > b) - (a < b)


def equal(a, b):
    """Three-valued equality as a truth value."""
    c = compare(a, b)
    return None if c is None else c == 0


def like_regex(pattern):
    parts = []
    for ch in pattern:
        if ch == "%":
            parts.append(".*")
        elif ch == "_":
            parts.append(".")
        else:
            parts.append(re.escape(ch))
    return re.compile("".join(parts), re.DOTALL | re.IGNORECASE)
