        if self.is_kw(word):
            self.pos += 1
            return True
        return False

    def accept_op(self, op):
        if self.is_op(op):
            self.pos += 1
            return True
        return False

    def expect_kw(self, word):
        if not self.accept_kw(word):
            raise SQLError(f"expected {word}, got {self.peek()[1]!r}")

    def expect_op(self, op):
        if not self.accept_op(op):
            raise SQLError(f"expected {op!r}, got {self.peek()[1]!r}")

    def parse_query(self):
        self.expect_kw("SELECT")
        items = [self.parse_item()]
        while self.accept_op(","):
            items.append(self.parse_item())
        if self.is_kw("FROM"):
            raise SQLError("FROM is not supported yet")
        self.accept_op(";")
        if self.peek()[0] != "end":
            raise SQLError(f"unexpected token {self.peek()[1]!r}")
        return items

    def parse_item(self):
        e = self.parse_expr()
        alias = None
        if self.accept_kw("AS"):
            t = self.advance()
            if t[0] != "id":
                raise SQLError("expected alias name")
            alias = t[1]
        elif self.peek()[0] == "id":
            alias = self.advance()[1]
        return (e, alias)

    # precedence, loosest first: OR, AND, NOT, comparisons, +-, */%, ||, unary
    def parse_expr(self):
        e = self.parse_and()
        while self.accept_kw("OR"):
            e = ("bin", "OR", e, self.parse_and())
        return e

    def parse_and(self):
        e = self.parse_not()
        while self.accept_kw("AND"):
            e = ("bin", "AND", e, self.parse_not())
        return e

    def parse_not(self):
        if self.accept_kw("NOT"):
            return ("not", self.parse_not())
        return self.parse_cmp()

    def parse_cmp(self):
        e = self.parse_add()
        while True:
            t = self.peek()
            if t[0] == "op" and t[1] in CMP_OPS:
