                e = ("bin", "=" if t[1] == "==" else t[1], e, self.parse_add())
            elif self.is_kw("IS"):
                self.advance()
                neg = self.accept_kw("NOT")
                self.expect_kw("NULL")
                e = ("isnull", e, neg)
