            name = t[1].upper()
            args = []
            if not self.accept_op(")"):
                args.append(self.parse_expr())
                while self.accept_op(","):
                    args.append(self.parse_expr())
                self.expect_op(")")
            return ("func", name, args)
        raise SQLError(f"unexpected token {t[1]!r}")

