        base = None
        if not self.is_kw("WHEN"):
            base = self.parse_expr()
        whens = []
        while self.accept_kw("WHEN"):
            c = self.parse_expr()
            self.expect_kw("THEN")
            whens.append((c, self.parse_expr()))
        if not whens:
            raise SQLError("CASE needs WHEN")
        els = self.parse_expr() if self.accept_kw("ELSE") else None
        self.expect_kw("END")
        return ("case", base, whens, els)


