# ---- evaluator -------------------------------------------------------------

def arith(op, a, b):
    if a is None or b is None:
        return None
    a, b = to_num(a), to_num(b)
    if op == "+":
        return a + b
    if op == "-":
        return a - b
    if op == "*":
        return a * b
    if b == 0:
        return None
    return int_div(a, b) if op == "/" else int_mod(a, b)


def substr(s, start, length=None):
    n = len(s)
    p = start
    if p < 0:
        p = n + p + 1
    if length is None:
        lo, hi = p, n + 1
    elif length >= 0:
        lo, hi = p, p + length
    else:
        lo, hi = p + length, p
    lo, hi = max(lo, 1), min(hi, n + 1)
    return s[lo - 1:hi - 1] if hi > lo else ""


def call_func(name, args, ev):
    def need(k):
        if len(args) != k:
            raise SQLError(f"wrong number of arguments to {name}()")
    if name == "COALESCE":
        if not args:
            raise SQLError("wrong number of arguments to COALESCE()")
        for a in args:
            v = ev(a)
            if v is not None:
                return v
        return None
    if name == "NULLIF":
        need(2)
        a, b = ev(args[0]), ev(args[1])
        return None if equal(a, b) else a
    if name in ("UPPER", "LOWER", "LENGTH", "ABS"):
        need(1)
        v = ev(args[0])
        if v is None:
            return None
        if name == "UPPER":
            return to_text(v).upper()
        if name == "LOWER":
            return to_text(v).lower()
        if name == "LENGTH":
            return len(to_text(v))
        return abs(to_num(v))
    if name == "SUBSTR":
        if len(args) not in (2, 3):
            raise SQLError("wrong number of arguments to SUBSTR()")
        vals = [ev(a) for a in args]
        if any(v is None for v in vals):
            return None
        length = to_num(vals[2]) if len(vals) == 3 else None
        return substr(to_text(vals[0]), to_num(vals[1]), length)
    raise SQLError(f"no such function: {name}")


def ev(node):
    kind = node[0]
    if kind == "lit":
        return node[1]
    if kind == "neg":
        v = ev(node[1])
        return None if v is None else -to_num(v)
    if kind == "not":
        return from_truth(None if truth(ev(node[1])) is None else not truth(ev(node[1])))
    if kind == "isnull":
        is_null = ev(node[1]) is None
        return 1 if (is_null != node[2]) else 0
    if kind == "bin":
        return ev_bin(node[1], node[2], node[3])
    if kind == "between":
        x, lo, hi, neg = ev(node[1]), ev(node[2]), ev(node[3]), node[4]
        c1, c2 = compare(x, lo), compare(x, hi)
        t = and3(None if c1 is None else c1 >= 0, None if c2 is None else c2 <= 0)
        return from_truth(not t if (neg and t is not None) else t)
    if kind == "in":
        x = ev(node[1])
        found, saw_null = False, x is None
        for item in node[2]:
            v = ev(item)
            if v is None:
                saw_null = True
            elif x is not None and compare(x, v) == 0:
                found = True
                break
        t = True if found else (None if saw_null else False)
        if node[3] and t is not None:
            t = not t
        return from_truth(t)
    if kind == "like":
        x, p = ev(node[1]), ev(node[2])
        if x is None or p is None:
            return None
        m = like_regex(to_text(p)).fullmatch(to_text(x)) is not None
        return 1 if m != node[3] else 0
    if kind == "case":
        return ev_case(node)
    if kind == "func":
        return call_func(node[1], node[2], ev)
    raise SQLError(f"bad node {kind}")


def and3(a, b):
    if a is False or b is False:
        return False
    if a is None or b is None:
        return None
    return True


def ev_bin(op, an, bn):
    if op == "AND":
        a = truth(ev(an))
        b = truth(ev(bn))
        return from_truth(and3(a, b))
    if op == "OR":
        a, b = truth(ev(an)), truth(ev(bn))
        if a is True or b is True:
            return 1
        if a is None or b is None:
            return None
        return 0
    a, b = ev(an), ev(bn)
    if op == "||":
        if a is None or b is None:
            return None
        return to_text(a) + to_text(b)
    if op in CMP_OPS:
        c = compare(a, b)
        if c is None:
            return None
        ok = {"=": c == 0, "!=": c != 0, "<>": c != 0, "<": c < 0,
              "<=": c <= 0, ">": c > 0, ">=": c >= 0}[op]
        return 1 if ok else 0
    return arith(op, a, b)


def ev_case(node):
    _, base, whens, els = node
    if base is not None:
        x = ev(base)
        for cond, val in whens:
            if x is not None and compare(x, ev(cond)) == 0:
                return ev(val)
    else:
        for cond, val in whens:
            if truth(ev(cond)):
                return ev(val)
    return ev(els) if els is not None else None


def evaluate_query(sql):
    items = parse(sql)
    row = tuple(ev(e) for e, _ in items)
    return [row]
