def ev_bin(op, an, bn):
    if op == "AND":
        return from_truth(and3(truth(ev(an)), truth(ev(bn))))
    if op == "OR":
        a, b = truth(ev(an)), truth(ev(bn))
        if a is True or b is True:
            return 1
        if a is None or b is None:
            return None
        return 0
    a, b = ev(an), ev(bn)
    if op == "||":
        if a is None or b is None:
            return None
        return to_text(a) + to_text(b)
    if op in CMP_OPS:
        c = compare(a, b)
        if c is None:
            return None
        ok = {"=": c == 0, "!=": c != 0, "<>": c != 0, "<": c < 0,
              "<=": c <= 0, ">": c > 0, ">=": c >= 0}[op]
        return 1 if ok else 0
    return arith(op, a, b)


def ev_case(node):
    _, base, whens, els = node
    for cond, val in whens:
        if base is not None:
            x = ev(base)
            hit = x is not None and compare(x, ev(cond)) == 0
        else:
            hit = truth(ev(cond)) is True
        if hit:
            return ev(val)
    return ev(els) if els is not None else None


def evaluate_query(sql):
    items = parse(sql)
    return [tuple(ev(e) for e, _ in items)]
