"""SELECT statements over tables (checkpoints 1-2)."""
import functools

from minisql.engine import SQLError, Parser, ev, truth, compare, to_num


class Env:
    """Column lookup for one row. sources: list of (qualifier, column names, row tuple)."""

    def __init__(self, sources):
        self.sources = sources

    def lookup(self, qual, name):
        found = []
        for q, cols, row in self.sources:
            if qual is not None and (q is None or q.lower() != qual.lower()):
                continue
            for idx, c in enumerate(cols):
                if c.lower() == name.lower():
                    found.append(row[idx])
        if not found:
            raise SQLError(f"no such column: {name if qual is None else qual + '.' + name}")
        if len(found) > 1:
            raise SQLError(f"ambiguous column name: {name}")
        return found[0]


class Select:
    def __init__(self):
        self.distinct = False
        self.items = []      # ('star', qual) or ('expr', node, alias)
        self.table = None    # table name
        self.alias = None
        self.where = None
        self.order = []      # (node, desc)
        self.limit = None
        self.offset = None


def parse_select(sql):
    p = Parser(sql)
    s = Select()
    p.expect_kw("SELECT")
    s.distinct = p.accept_kw("DISTINCT")
    while True:
        if p.accept_op("*"):
            s.items.append(("star", None))
        elif p.peek()[0] == "id" and p.is_op(".", 1) and p.is_op("*", 2):
            s.items.append(("star", p.advance()[1]))
            p.advance()
            p.advance()
        else:
            e, alias = p.parse_item()
            s.items.append(("expr", e, alias))
        if not p.accept_op(","):
            break
    if p.accept_kw("FROM"):
        t = p.advance()
        if t[0] != "id":
            raise SQLError("expected table name")
        s.table = t[1]
        if p.accept_kw("AS"):
            s.alias = p.advance()[1]
        elif p.peek()[0] == "id":
            s.alias = p.advance()[1]
    if p.accept_kw("WHERE"):
        s.where = p.parse_expr()
    if p.accept_kw("ORDER"):
        p.expect_kw("BY")
        while True:
            e = p.parse_expr()
            desc = False
            if p.accept_kw("DESC"):
                desc = True
            else:
                p.accept_kw("ASC")
            s.order.append((e, desc))
            if not p.accept_op(","):
                break
    if p.accept_kw("LIMIT"):
        s.limit = p.parse_expr()
        if p.accept_kw("OFFSET"):
            s.offset = p.parse_expr()
    p.accept_op(";")
    if p.peek()[0] != "end":
        raise SQLError(f"unexpected token {p.peek()[1]!r}")
    return s
