        groups.setdefault(key, []).append(e)
    return [GroupEnv(rows, tables, outer) for rows in groups.values()]


def run_select(s, tables, outer=None):
    """Run a parsed SELECT. Returns (output column names, rows)."""
    if s.ctes:
        local = dict(tables)
        for name, cols, sub in s.ctes:
            names, rows = run_select(sub, local, None)
            local[name] = (cols if cols else names, rows)
        tables = local
    envs, names = _envs_and_names(s, tables, outer)
    terms = _order_terms(s, names)
    if s.where is not None:
        envs = [e for e in envs if truth(ev(s.where, e)) is True]
    produced = []
    for ctx in _contexts(s, envs, tables, outer):
        if s.having is not None and truth(ev(s.having, ctx)) is not True:
