        for it in s.items:
            if it[0] == "star":
                if not isinstance(ctx, Env):
                    raise SQLError("* is not allowed in an aggregate query")
                for q, _, r in ctx.sources:
                    if it[1] is None or (q is not None and it[1].lower() == q.lower()):
