            else:
                out.append(ev(it[1], ctx))
        keys = [out[val] if kind == "out" else ev(val, ctx) for kind, val in (t for t, _ in terms)]
        produced.append((tuple(out), keys))
    if s.distinct:
        seen, unique = set(), []
        for out, keys in produced:
            if out not in seen:
                seen.add(out)
                unique.append((out, keys))
        produced = unique
    descs = [d for _, d in terms]

    def cmp(a, b):
        for idx, desc in enumerate(descs):
            c = _cmp_values(a[1][idx], b[1][idx])
            if c:
                return -c if desc else c
        return 0

    if terms:
        produced.sort(key=functools.cmp_to_key(cmp))
    result = [out for out, _ in produced]
    off = _intval(s.offset) if s.offset is not None else 0
    result = result[max(off, 0):]
    if s.limit is not None:
        lim = _intval(s.limit)
        if lim >= 0:
            result = result[:lim]
    return names, result


def execute(sql, tables):
    return run_select(parse_select(sql), tables)[1]
