def _eval_window(w, ctxs):
    """Value of one window node for every context (group or row), in the order of ctxs."""
    fn, (partition, order, frame) = w[1], w[2]
    odesc = [d for _, d in order]
    okeys = [[ev(e, c) for e, _ in order] for c in ctxs]
    parts = {}
    for i, c in enumerate(ctxs):
        key = tuple(ev(e, c) for e in partition)
        parts.setdefault(key, []).append(i)
    result = [None] * len(ctxs)

    def cmp_rows(a, b):
        for k, desc in enumerate(odesc):
            c = _cmp_values(okeys[a][k], okeys[b][k])
            if c:
                return -c if desc else c
        return 0

    def same(a, b):
        return cmp_rows(a, b) == 0

    for idxs in parts.values():
        idxs = sorted(idxs, key=functools.cmp_to_key(cmp_rows))
        m = len(idxs)
        pf, pl, dense = [0] * m, [0] * m, [0] * m
        start, groups = 0, 0
        while start < m:
            end = start
            while end + 1 < m and same(idxs[end + 1], idxs[start]):
                end += 1
            groups += 1
            for p in range(start, end + 1):
                pf[p], pl[p], dense[p] = start, end, groups
            start = end + 1
        for p in range(m):
            ci = idxs[p]
            if frame is None:
                lo, hi = 0, (pl[p] if order else m - 1)
            else:
                lo, hi = max(_bound_lo(frame[0], p, m), 0), min(_bound_hi(frame[1], p, m), m - 1)
            result[ci] = _window_value(fn, ctxs, idxs, p, lo, hi, pf, dense, m, ci)
    return result


def _window_value(fn, ctxs, idxs, p, lo, hi, pf, dense, m, ci):
    cur = ctxs[ci]
    if fn[0] == "agg":
        _, name, arg, distinct = fn
        if arg is None:
            return max(hi - lo + 1, 0) if name == "COUNT" else None
        return _aggregate(name, [ev(arg, ctxs[idxs[q]]) for q in range(lo, hi + 1)], distinct)
    name, args = fn[1], fn[2]
    if name == "ROW_NUMBER":
        return p + 1
    if name == "RANK":
        return pf[p] + 1
    if name == "DENSE_RANK":
        return dense[p]
    if name == "NTILE":
        k = to_num(ev(args[0], cur))
        q, r = divmod(m, k)
        if p < r * (q + 1):
            return p // (q + 1) + 1
        return r + (p - r * (q + 1)) // q + 1
    if name in ("LAG", "LEAD"):
        off = to_num(ev(args[1], cur)) if len(args) > 1 else 1
        target = p - off if name == "LAG" else p + off
        if 0 <= target < m:
            return ev(args[0], ctxs[idxs[target]])
        return ev(args[2], cur) if len(args) > 2 else None
    if name in ("FIRST_VALUE", "LAST_VALUE"):
        if lo > hi:
            return None
        return ev(args[0], ctxs[idxs[lo if name == "FIRST_VALUE" else hi]])
    raise SQLError(f"no such window function: {name}")
