def _recursive(name, cols, sub, tables):
    """Rows of a recursive CTE: start rows, then step rows on the rows the previous run added."""
    start = copy.copy(sub)
    start.compounds, start.order, start.limit, start.offset = [], [], None, None
    names, rows0 = run_select(start, tables, None)
    cols = cols or names
    op, step = sub.compounds[0]
    union_all = op == "UNION ALL"
    seen = set()

    def admit(rows):
        new = []
        for r in rows:
            if union_all or r not in seen:
                seen.add(r)
                new.append(r)
        return new

    working = admit(rows0)
    result = list(working)
    while working:
        local = dict(tables)
        local[name] = (cols, working)
        _, _, prod = run_core(step, local, None, False)
        working = admit([out for out, _ in prod])
        result.extend(working)
    return cols, result


def _with_ctes(s, tables):
    local = dict(tables)
    for name, cols, sub in s.ctes:
        if s.recursive and sub.compounds and sub.compounds[0][0] in ("UNION", "UNION ALL"):
            local[name] = _recursive(name, cols, sub, local)
        else:
            names, rows = run_select(sub, local, None)
            local[name] = (cols or names, rows)
    return local


def _finish(s, terms, produced):
    descs = [d for _, d in terms]

    def cmp(a, b):
        for idx, desc in enumerate(descs):
            c = _cmp_values(a[1][idx], b[1][idx])
            if c:
                return -c if desc else c
        return 0

    if terms:
        produced.sort(key=functools.cmp_to_key(cmp))
    result = [out for out, _ in produced]
    off = _intval(s.offset) if s.offset is not None else 0
    result = result[max(off, 0):]
    if s.limit is not None:
        lim = _intval(s.limit)
        if lim >= 0:
            result = result[:lim]
    return result


def run_select(s, tables, outer=None):
    """Run a parsed SELECT (with its compound parts). Returns (output column names, rows)."""
    if s.ctes:
        tables = _with_ctes(s, tables)
    names, terms, produced = run_core(s, tables, outer, not s.compounds)
    if s.compounds:
        rows = [out for out, _ in produced]
        for op, core in s.compounds:
            _, _, prod2 = run_core(core, tables, outer, False)
            rows = _combine(op, rows, [out for out, _ in prod2])
        terms = _order_terms(s, names)
        for (kind, _), _ in terms:
            if kind != "out":
                raise SQLError("ORDER BY term does not match any column in the result set")
        produced = [(r, [r[v] for (_, v), _ in terms]) for r in rows]
    return names, _finish(s, terms, produced)


def execute(sql, tables):
    return run_select(parse_select(sql), tables)[1]
