    def ident(self):
        t = self.advance()
        if t[0] != 'ident':
            raise SQLError(f"expected a name, got {t[1]!r}")
        return t[1]

    def parse_item(self):
        if self.accept_op('*'):
            return ('star', None), None
        if self.peek()[0] == 'ident' and self.peek(1) == ('op', '.') and self.peek(2) == ('op', '*'):
            name = self.ident()
            self.pos += 2
            return ('star', name), None
        e = self.parse_expr()
        if self.accept_kw('as'):
            return e, self.ident()
        if self.peek()[0] == 'ident' and self.peek()[1].lower() not in RESERVED:
            return e, self.advance()[1]
        return e, None

    def parse_query(self):
        self.expect_kw('select')
        distinct = self.accept_kw('distinct')
        items = [self.parse_item()]
        while self.accept_op(','):
            items.append(self.parse_item())
        table = None
        if self.accept_kw('from'):
            name = self.ident()
            alias = None
            if self.accept_kw('as'):
                alias = self.ident()
            elif self.peek()[0] == 'ident' and self.peek()[1].lower() not in RESERVED:
                alias = self.advance()[1]
            table = (name, alias)
        where = self.parse_expr() if self.accept_kw('where') else None
        order = []
        if self.accept_kw('order'):
            self.expect_kw('by')
            while True:
                e = self.parse_expr()
                desc = self.accept_kw('desc')
                if not desc:
                    self.accept_kw('asc')
                order.append((e, desc))
                if not self.accept_op(','):
                    break
        limit = offset = None
        if self.accept_kw('limit'):
            limit = self.parse_expr()
            if self.accept_kw('offset'):
                offset = self.parse_expr()
        self.accept_op(';')
        if self.peek()[0] != 'eof':
            raise SQLError(f"unexpected {self.peek()[1]!r}")
        return {'distinct': distinct, 'items': items, 'table': table, 'where': where,
                'order': order, 'limit': limit, 'offset': offset}

