        k = src.lower()
        if k in ctes:
            return ctes[k]
        if k in self.tables:
            return self.tables[k]
        raise SQLError(f"no such table: {src}")

    def execute(self, q, outer, ctes):
        """Run a query; returns (column names, rows)."""
        ctes = dict(ctes)
        for name, colnames, sub in q['with']:
            names, rows = self.execute(sub, None, ctes)
            ctes[name.lower()] = (colnames or names, rows)
        run = lambda sub, env: self.execute(sub, env, ctes)
        if q['from'] is None:
            scope, rows = None, [()]
        else:
