                    for r in right:
                        row = l + tuple(r)
                        if on is None or truth(ev(on, RowEnv(scope, row, outer, run))) == 1:
                            new.append(row)
                            hit = True
                    if not hit and kind == 'left':
                        new.append(l + (None,) * len(cols))
                rows = new
