        for e, alias in q['items']:
            if e[0] == 'star':
                if scope is None:
                    raise SQLError("no tables specified")
                scope.check(e[1])
                items.extend((('col', qual, c), None) for qual, c in scope.names
                             if e[1] is None or qual == e[1].lower())
            else:
                items.append((e, alias))
        names = [alias or (e[2] if e[0] == 'col' else f'column{i + 1}') for i, (e, alias) in enumerate(items)]
