from .evaluate import ev, to_num, key
from .envs import sort_key


class WinEnv:
    """Environment that also knows the value of each window function for its row."""

    def __init__(self, base, vals):
        self.base, self.vals = base, vals

    def col(self, qual, name):
        return self.base.col(qual, name)

    def agg(self, node):
        return self.base.agg(node)

    def sub(self, node):
        return self.base.sub(node)

    def win(self, node):
        return self.vals[id(node)]


def collect(x, out):
    if isinstance(x, tuple) and x and x[0] == 'win':
        out.append(x)
    elif isinstance(x, (tuple, list)):
        for i in x:
            collect(i, out)
    return out


def bound(kind, n, p, size):
    """Absolute position (within the partition) of one frame bound."""
    if kind == 'unb_p':
        return 0
    if kind == 'unb_f':
        return size - 1
    if kind == 'cur':
        return p
    if kind == 'prec':
        return p - n
    return p + n  # 'fol'


def ntile(p, size, k):
    each, extra = divmod(size, k)
    big = extra * (each + 1)
    if p < big:
        return p // (each + 1) + 1
    return extra + (p - big) // each + 1


def aggregate(fname, args, xv, fr):
    if fname == 'first_value':
        return xv[fr[0]] if fr else None
    if fname == 'last_value':
        return xv[fr[-1]] if fr else None
    if fname == 'count' and not args:
        return len(fr)
    vals = [xv[i] for i in fr if xv[i] is not None]
    if fname == 'count':
        return len(vals)
    if not vals:
        return None
    if fname == 'sum':
        return sum(to_num(v) for v in vals)
    return (min if fname == 'min' else max)(vals, key=key)
