        size = len(rows)
        kk = [tuple(sort_key(v) for v in okeys[i]) for i in rows]
        pstart, pend, dense = list(range(size)), list(range(size)), [1] * size
        for p in range(1, size):
            same = kk[p] == kk[p - 1]
            pstart[p] = pstart[p - 1] if same else p
            dense[p] = dense[p - 1] if same else dense[p - 1] + 1
        for p in range(size - 2, -1, -1):
