                q = p - off if fname == 'lag' else p + off
                if 0 <= q < size:
                    v = xv[rows[q]]
                else:
                    v = ev(args[2], env) if len(args) > 2 else None
            else:
                if frame is None:
                    lo, hi = 0, (pend[p] if order else size - 1)
                else:
                    (sk, sn), (ek, en) = frame
                    lo = max(bound(sk, sn, p, size), 0)
                    hi = min(bound(ek, en, p, size), size - 1)
                fr = rows[lo:hi + 1] if lo <= hi else []
                v = aggregate(fname, args, xv, fr)
            res[i] = v
    return res


def with_windows(exprs, envs):
    wins = collect(exprs, [])
    if not wins:
        return envs
    vals = [{} for _ in envs]
    for node in wins:
