import re

from .lexer import SQLError


def to_num(v):
    if v is None or isinstance(v, int):
        return v
    m = re.match(r'\s*[-+]?\d+', v)
    return int(m.group()) if m else 0


def to_text(v):
    return None if v is None else str(v)


def key(v):
    """Sort/compare key: numbers sort before text, as in SQLite."""
    return (1, v) if isinstance(v, int) else (2, v)


def truth(v):
    """Three-valued truth: 1, 0 or None."""
    if v is None:
        return None
    return 1 if to_num(v) != 0 else 0


def and3(a, b):
    if a == 0 or b == 0:
        return 0
    if a is None or b is None:
        return None
    return 1


def or3(a, b):
    if a == 1 or b == 1:
        return 1
    if a is None or b is None:
        return None
    return 0


def not3(a):
    return None if a is None else 1 - a


def cmp3(a, b, op):
    if a is None or b is None:
        return None
    ka, kb = key(a), key(b)
    return int({'=': ka == kb, '!=': ka != kb, '<': ka < kb,
                '<=': ka <= kb, '>': ka > kb, '>=': ka >= kb}[op])


def arith(op, a, b):
    if a is None or b is None:
        return None
    x, y = to_num(a), to_num(b)
    if op == '+':
        return x + y
    if op == '-':
        return x - y
    if op == '*':
        return x * y
    if y == 0:
        return None
    if op == '/':  # truncates toward zero
        q = abs(x) // abs(y)
        return q if (x < 0) == (y < 0) else -q
    r = abs(x) % abs(y)  # '%': sign of the left operand
    return r if x >= 0 else -r


def like(pat, s):
    rx = ''.join('.*' if c == '%' else '.' if c == '_' else re.escape(c) for c in pat)
    return 1 if re.fullmatch(rx, s, re.I | re.S) else 0


def substr(s, start, length=None):
    n = len(s)
    if start < 0:
        start = n + start + 1
    if length is None:
        lo, hi = start, n + 1
    elif length < 0:
        lo, hi = start + length, start
    else:
        lo, hi = start, start + length
    lo, hi = max(lo, 1), min(hi, n + 1)
    return s[lo - 1:hi - 1] if hi > lo else ''


def call(name, vals):
    if name == 'coalesce':
