def ev(n):
    k = n[0]
    if k == 'lit':
        return n[1]
    if k == 'neg':
        v = ev(n[1])
        return None if v is None else -to_num(v)
    if k == 'bin':
        return arith(n[1], ev(n[2]), ev(n[3]))
    if k == 'concat':
        a, b = ev(n[1]), ev(n[2])
        return None if a is None or b is None else to_text(a) + to_text(b)
    if k == 'cmp':
        return cmp3(ev(n[2]), ev(n[3]), n[1])
    if k == 'and':
        return and3(truth(ev(n[1])), truth(ev(n[2])))
    if k == 'or':
        return or3(truth(ev(n[1])), truth(ev(n[2])))
    if k == 'not':
        return not3(truth(ev(n[1])))
    if k == 'isnull':
        r = ev(n[1]) is None
        return int(not r if n[2] else r)
    if k == 'between':
        x = ev(n[1])
        r = and3(cmp3(x, ev(n[2]), '>='), cmp3(x, ev(n[3]), '<='))
        return not3(r) if n[4] else r
    if k == 'in':
        x = ev(n[1])
        vals = [ev(i) for i in n[2]]
        if x is None:
            r = None
        elif any(v is not None and key(v) == key(x) for v in vals):
            r = 1
        elif any(v is None for v in vals):
            r = None
        else:
            r = 0
        return not3(r) if n[3] else r
    if k == 'like':
        x, p = ev(n[1]), ev(n[2])
        r = None if x is None or p is None else like(to_text(p), to_text(x))
        return not3(r) if n[3] else r
    if k == 'case':
        base, whens, els = n[1], n[2], n[3]
        bv = None if base is None else ev(base)
        for c, v in whens:
            if base is None:
                if truth(ev(c)) == 1:
                    return ev(v)
            elif cmp3(bv, ev(c), '=') == 1:
                return ev(v)
        return None if els is None else ev(els)
    if k == 'call':
        return call(n[1], [ev(a) for a in n[2]])
    raise SQLError(f"cannot evaluate {k}")
