class GroupEnv:
    """One group: columns come from its first row, aggregates over all of its rows."""

    def __init__(self, scope, rows, outer=None, run=None):
        self.scope, self.rows, self.outer, self.run = scope, rows, outer, run

    def col(self, qual, name):
        if self.rows:
            return RowEnv(self.scope, self.rows[0], self.outer, self.run).col(qual, name)
        if self.scope is not None and self.scope.find(qual, name) is not None:
            return None
        if self.outer is not None:
            return self.outer.col(qual, name)
        raise SQLError(f"no such column: {name}")

    def agg(self, node):
        _, fname, distinct, arg = node
        if arg is None:
            return len(self.rows)
        vals = [v for v in (ev(arg, RowEnv(self.scope, r, self.outer, self.run)) for r in self.rows)
                if v is not None]
        if distinct:
            vals = list(dict.fromkeys(vals))
        if fname == 'count':
            return len(vals)
        if not vals:
            return None
        if fname == 'sum':
            return sum(to_num(v) for v in vals)
        return (min if fname == 'min' else max)(vals, key=key)

    def sub(self, node):
        return self.run(node, self)


NO_ENV = RowEnv(None, ())


def has_agg(x):
    if isinstance(x, tuple) and x and x[0] == 'agg':
        return True
    if isinstance(x, (tuple, list)):
        return any(has_agg(i) for i in x)
    return False


def sort_key(v):
