            self.expect_kw('by')
            while True:
                e = self.parse_expr()
                desc = self.accept_kw('desc')
                if not desc:
                    self.accept_kw('asc')
                order.append((e, desc))
                if not self.accept_op(','):
                    break
        frame = None
        if self.accept_kw('rows') or self.accept_kw('range'):
            if self.accept_kw('between'):
                s = self.parse_bound()
                self.expect_kw('and')
                frame = (s, self.parse_bound())
            else:
                frame = (self.parse_bound(), ('cur', 0))
        self.expect_op(')')
        return part, order, frame

    def parse_bound(self):
        if self.accept_kw('unbounded'):
            if self.accept_kw('preceding'):
                return ('unb_p', 0)
            self.expect_kw('following')
            return ('unb_f', 0)
        if self.accept_kw('current'):
            self.expect_kw('row')
            return ('cur', 0)
        t = self.advance()
        if t[0] != 'num':
            raise SQLError("bad window frame bound")
        if self.accept_kw('preceding'):
            return ('prec', t[1])
        self.expect_kw('following')
        return ('fol', t[1])

    def parse_compound(self):
        first = self.parse_select()
        sets = []
        while self.is_kw('union') or self.is_kw('intersect') or self.is_kw('except'):
            op = self.advance()[1].lower()
            allf = self.accept_kw('all')
            sets.append((op, allf, self.parse_select()))
        if not sets:
            return first
        last = sets[-1][2]
        comp = {'first': first, 'sets': sets, 'order': last['order'], 'limit': last['limit'],
                'offset': last['offset'], 'with': []}
        last['order'], last['limit'], last['offset'] = [], None, None
        return comp

