def compute(node, envs):
    """Value of one window function for every environment (row or group)."""
    _, fname, args, part, order, frame = node
    okeys = [[ev(e, env) for e, _ in order] for env in envs]
    xv = [ev(args[0], env) for env in envs] if args and fname != 'ntile' else None
    groups = {}
    for i, env in enumerate(envs):
        groups.setdefault(tuple(ev(p, env) for p in part), []).append(i)
    res = [None] * len(envs)
    for idxs in groups.values():
        rows = list(idxs)
        for j in reversed(range(len(order))):
            rows.sort(key=lambda i, j=j: sort_key(okeys[i][j]), reverse=order[j][1])
        size = len(rows)
        kk = [tuple(sort_key(v) for v in okeys[i]) for i in rows]
        pstart, pend, dense = list(range(size)), list(range(size)), [1] * size
        for p in range(1, size):
            same = kk[p] == kk[p - 1]
            pstart[p] = pstart[p - 1] if same else p
            dense[p] = dense[p - 1] if same else dense[p - 1] + 1
        for p in range(size - 2, -1, -1):
            if kk[p] == kk[p + 1]:
                pend[p] = pend[p + 1]
        for p, i in enumerate(rows):
            env = envs[i]
            if fname == 'row_number':
                v = p + 1
            elif fname == 'rank':
                v = pstart[p] + 1
            elif fname == 'dense_rank':
                v = dense[p]
            elif fname == 'ntile':
                v = ntile(p, size, max(int(to_num(ev(args[0], env))), 1))
            elif fname in ('lag', 'lead'):
                off = to_num(ev(args[1], env)) if len(args) > 1 else 1
                q = p - off if fname == 'lag' else p + off
                if 0 <= q < size:
                    v = xv[rows[q]]
                else:
                    v = ev(args[2], env) if len(args) > 2 else None
            else:
                if frame is None:
                    lo, hi = 0, (pend[p] if order else size - 1)
                else:
                    (sk, sn), (ek, en) = frame
                    lo = max(bound(sk, sn, p, size), 0)
                    hi = min(bound(ek, en, p, size), size - 1)
                fr = rows[lo:hi + 1] if lo <= hi else []
                v = aggregate(fname, args, xv, fr)
            res[i] = v
    return res


def with_windows(exprs, envs):
    wins = collect(exprs, [])
    if not wins:
        return envs
    vals = [{} for _ in envs]
    for node in wins:
        for i, v in enumerate(compute(node, envs)):
            vals[i][id(node)] = v
    return [WinEnv(e, vals[i]) for i, e in enumerate(envs)]
