    def distinct(self, rows):
        seen, out = set(), []
        for r in rows:
            if r not in seen:
                seen.add(r)
                out.append(r)
        return out

    def compound(self, q, outer, ctes):
        """UNION / INTERSECT / EXCEPT, applied left to right, then ORDER BY and LIMIT."""
        names, rows = self.execute(q['first'], outer, ctes)
        rows = list(rows)
        for op, allf, sel in q['sets']:
            _, other = self.execute(sel, outer, ctes)
            other = list(other)
            if op == 'union':
                rows = rows + other if allf else self.distinct(rows + other)
            elif op == 'intersect':
                rows = self.distinct([r for r in rows if r in set(other)])
            else:
                rows = self.distinct([r for r in rows if r not in set(other)])
        lower = [n.lower() for n in names]
        for e, desc in reversed(q['order']):
            if e[0] == 'lit' and isinstance(e[1], int):
                if not 1 <= e[1] <= len(names):
                    raise SQLError("ORDER BY term out of range")
                idx = e[1] - 1
            elif e[0] == 'col' and e[1] is None and e[2].lower() in lower:
                idx = lower.index(e[2].lower())
            else:
                raise SQLError("ORDER BY on a compound query must use a column name or position")
            rows = sorted(rows, key=lambda r, idx=idx: sort_key(r[idx]), reverse=desc)
        off = to_num(ev(q['offset'], NO_ENV)) if q['offset'] is not None else 0
        lim = to_num(ev(q['limit'], NO_ENV)) if q['limit'] is not None else None
        rows = rows[max(off or 0, 0):]
        if lim is not None and lim >= 0:
            rows = rows[:lim]
        return names, rows
